        "content": "/**\n * Custom YAML parser implementation - lexer and parser.\n * No external dependencies - built from scratch.\n */\n\n// ============================================================================\n// Types\n// ============================================================================\n\nexport interface YamlParseSuccess {\n  success: true;\n  data: YamlValue;\n}\n\nexport interface YamlParseError {\n  success: false;\n  error: string;\n  line: number;\n  column?: number;\n}\n\nexport type YamlParseResult = YamlParseSuccess | YamlParseError;\n\nexport type YamlValue =\n  | string\n  | number\n  | boolean\n  | null\n  | YamlValue[]\n  | { [key: string]: YamlValue };\n\n// ============================================================================\n// Lexer\n// ============================================================================\n\nenum TokenType {\n  KEY = \"KEY\",\n  COLON = \"COLON\",\n  STRING = \"STRING\",\n  NUMBER = \"NUMBER\",\n  BOOLEAN = \"BOOLEAN\",\n  NULL = \"NULL\",\n  DASH = \"DASH\",\n  LBRACKET = \"LBRACKET\",\n  RBRACKET = \"RBRACKET\",\n  LBRACE = \"LBRACE\",\n  RBRACE = \"RBRACE\",\n  COMMA = \"COMMA\",\n  PIPE = \"PIPE\",\n  GT = \"GT\",\n  NEWLINE = \"NEWLINE\",\n  INDENT = \"INDENT\",\n  DEDENT = \"DEDENT\",\n  EOF = \"EOF\",\n}\n\ninterface Token {\n  type: TokenType;\n  value: string;\n  line: number;\n  column: number;\n}\n\nclass Lexer {\n  private input: string;\n  private pos: number = 0;\n  private line: number = 1;\n  private column: number = 1;\n  private indentStack: number[] = [0];\n  private tokens: Token[] = [];\n  private atLineStart: boolean = true;\n\n  constructor(input: string) {\n    this.input = input;\n  }\n\n  tokenize(): Token[] {\n    while (this.pos < this.input.length) {\n      if (this.atLineStart) {\n        this.handleIndentation();\n        this.atLineStart = false;\n      }\n\n      const char = this.peek();\n\n      if (char === \"\\n\") {\n        this.addToken(TokenType.NEWLINE, \"\\n\");\n        this.advance();\n        this.atLineStart = true;\n        continue;\n      }\n\n      if (char === \"\\r\") {\n        this.advance();\n        if (this.peek() === \"\\n\") {\n          this.addToken(TokenType.NEWLINE, \"\\n\");\n          this.advance();\n        }\n        this.atLineStart = true;\n        continue;\n      }\n\n      if (char === \"#\") {\n        this.skipComment();\n        continue;\n      }\n\n      if (char === \" \") {\n        this.advance();\n        continue;\n      }\n\n      if (char === \"\\t\") {\n        throw this.error(\"Tabs are not allowed in YAML indentation\");\n      }\n\n      if (char === \":\") {\n        this.advance();\n        if (this.peek() === \" \" || this.peek() === \"\\n\" || this.peek() === \"\\r\" || this.pos >= this.input.length) {\n          this.addToken(TokenType.COLON, \":\");\n        } else {\n          throw this.error(\"Colon must be followed by space or newline\");\n        }\n        continue;\n      }\n\n      if (char === \"-\") {\n        const next = this.peekAhead(1);\n        if (next === \" \" || next === \"\\n\" || next === \"\\r\" || this.pos + 1 >= this.input.length) {\n          this.addToken(TokenType.DASH, \"-\");\n          this.advance();\n          continue;\n        }\n      }\n\n      if (char === \"[\") {\n        this.addToken(TokenType.LBRACKET, \"[\");\n        this.advance();\n        continue;\n      }\n\n      if (char === \"]\") {\n        this.addToken(TokenType.RBRACKET, \"]\");\n        this.advance();\n        continue;\n      }\n\n      if (char === \"{\") {\n        this.addToken(TokenType.LBRACE, \"{\");\n        this.advance();\n        continue;\n      }\n\n      if (char === \"}\") {\n        this.addToken(TokenType.RBRACE, \"}\");\n        this.advance();\n        continue;\n      }\n\n      if (char === \",\") {\n        this.addToken(TokenType.COMMA, \",\");\n        this.advance();\n        continue;\n      }\n\n      if (char === \"|\") {\n        this.addToken(TokenType.PIPE, \"|\");\n        this.advance();\n        continue;\n      }\n\n      if (char === \">\") {\n        this.addToken(TokenType.GT, \">\");\n        this.advance();\n        continue;\n      }\n\n      if (char === '\"' || char === \"'\") {\n        this.readQuotedString(char);\n        continue;\n      }\n\n      this.readUnquotedValue();\n    }\n\n    while (this.indentStack.length > 1) {\n      this.indentStack.pop();\n      this.addToken(TokenType.DEDENT, \"\");\n    }\n\n    this.addToken(TokenType.EOF, \"\");\n    return this.tokens;\n  }\n\n  private handleIndentation(): void {\n    let indent = 0;\n    while (this.peek() === \" \") {\n      indent++;\n      this.advance();\n    }\n\n    if (this.peek() === \"\\t\") {\n      throw this.error(\"Tabs are not allowed in YAML indentation\");\n    }\n\n    if (this.peek() === \"\\n\" || this.peek() === \"\\r\" || this.peek() === \"#\") {\n      return;\n    }\n\n    if (this.pos >= this.input.length) {\n      return;\n    }\n\n    const currentIndent = this.indentStack[this.indentStack.length - 1];\n\n    if (indent > currentIndent) {\n      this.indentStack.push(indent);\n      this.addToken(TokenType.INDENT, \"\");\n    } else if (indent < currentIndent) {\n      while (this.indentStack.length > 1 && this.indentStack[this.indentStack.length - 1] > indent) {\n        this.indentStack.pop();\n        this.addToken(TokenType.DEDENT, \"\");\n      }\n      if (this.indentStack[this.indentStack.length - 1] !== indent) {\n        throw this.error(\"Inconsistent indentation\");\n      }\n    }\n  }\n\n  private readQuotedString(quote: string): void {\n    const startLine = this.line;\n    const startColumn = this.column;\n    this.advance();\n    let value = \"\";\n\n    while (this.pos < this.input.length && this.peek() !== quote) {\n      if (this.peek() === \"\\\\\") {\n        this.advance();\n        const escaped = this.peek();\n        if (escaped === \"n\") {\n          value += \"\\n\";\n        } else if (escaped === \"t\") {\n          value += \"\\t\";\n        } else if (escaped === \"r\") {\n          value += \"\\r\";\n        } else if (escaped === \"\\\\\" || escaped === quote) {\n          value += escaped;\n        } else {\n          value += \"\\\\\" + escaped;\n        }\n        this.advance();\n      } else if (this.peek() === \"\\n\") {\n        throw this.error(\"Unterminated string\");\n      } else {\n        value += this.peek();\n        this.advance();\n      }\n    }\n\n    if (this.pos >= this.input.length) {\n      throw { message: \"Unterminated string\", line: startLine, column: startColumn };\n    }\n\n    this.advance();\n    this.tokens.push({ type: TokenType.STRING, value, line: startLine, column: startColumn });\n  }\n\n  private readUnquotedValue(): void {\n    const startLine = this.line;\n    const startColumn = this.column;\n    let value = \"\";\n\n    while (this.pos < this.input.length) {\n      const char = this.peek();\n      if (char === \":\" && (this.peekAhead(1) === \" \" || this.peekAhead(1) === \"\\n\" || this.peekAhead(1) === \"\\r\" || this.pos + 1 >= this.input.length)) {\n        break;\n      }\n      if (char === \"\\n\" || char === \"\\r\" || char === \"#\" || char === \",\" || char === \"]\" || char === \"}\" || char === \"[\" || char === \"{\") {\n        break;\n      }\n      value += char;\n      this.advance();\n    }\n\n    value = value.trimEnd();\n\n    if (value === \"\") {\n      return;\n    }\n\n    const token = this.classifyValue(value, startLine, startColumn);\n    this.tokens.push(token);\n  }\n\n  private classifyValue(value: string, line: number, column: number): Token {\n    if (value === \"true\" || value === \"false\") {\n      return { type: TokenType.BOOLEAN, value, line, column };\n    }\n\n    if (value === \"null\" || value === \"~\") {\n      return { type: TokenType.NULL, value, line, column };\n    }\n\n    if (/^-?\\d+(\\.\\d+)?$/.test(value) || /^-?\\d+(\\.\\d+)?[eE][+-]?\\d+$/.test(value)) {\n      return { type: TokenType.NUMBER, value, line, column };\n    }\n\n    return { type: TokenType.STRING, value, line, column };\n  }\n\n  private skipComment(): void {\n    while (this.pos < this.input.length && this.peek() !== \"\\n\" && this.peek() !== \"\\r\") {\n      this.advance();\n    }\n  }\n\n  private peek(): string {\n    return this.input[this.pos] || \"\";\n  }\n\n  private peekAhead(offset: number): string {\n    return this.input[this.pos + offset] || \"\";\n  }\n\n  private advance(): void {\n    if (this.peek() === \"\\n\") {\n      this.line++;\n      this.column = 1;\n    } else {\n      this.column++;\n    }\n    this.pos++;\n  }\n\n  private addToken(type: TokenType, value: string): void {\n    this.tokens.push({ type, value, line: this.line, column: this.column });\n  }\n\n  private error(message: string): { message: string; line: number; column: number } {\n    return { message, line: this.line, column: this.column };\n  }\n}\n\n// ============================================================================\n// Parser\n// ============================================================================\n\ntype ParserContext = \"root\" | \"mapping\" | \"sequence\" | \"inline-mapping\" | \"inline-sequence\";\n\ninterface ParserState {\n  indent: number;\n  context: ParserContext;\n  expectingValue: boolean;\n}\n\nclass Parser {\n  private tokens: Token[];\n  private pos: number = 0;\n  private stateStack: ParserState[] = [{ indent: 0, context: \"root\", expectingValue: false }];\n\n  constructor(tokens: Token[]) {\n    this.tokens = tokens;\n  }\n\n  parse(): YamlParseResult {\n    try {\n      this.skipNewlines();\n\n      if (this.peek().type === TokenType.EOF) {\n        return { success: true, data: null };\n      }\n\n      const data = this.parseValue();\n      this.skipNewlines();\n\n      if (this.peek().type !== TokenType.EOF) {\n        const token = this.peek();\n        return {\n          success: false,\n          error: `Unexpected token: ${token.type}`,\n          line: token.line,\n          column: token.column,\n        };\n      }\n\n      return { success: true, data };\n    } catch (err: unknown) {\n      if (typeof err === \"object\" && err !== null && \"message\" in err && \"line\" in err) {\n        const e = err as { message: string; line: number; column?: number };\n        return { success: false, error: e.message, line: e.line, column: e.column };\n      }\n      return { success: false, error: String(err), line: 1 };\n    }\n  }\n\n  private parseValue(): YamlValue {\n    this.skipNewlines();\n    const token = this.peek();\n\n    if (token.type === TokenType.DASH) {\n      return this.parseSequence();\n    }\n\n    if (token.type === TokenType.LBRACKET) {\n      return this.parseInlineSequence();\n    }\n\n    if (token.type === TokenType.LBRACE) {\n      return this.parseInlineMapping();\n    }\n\n    if (token.type === TokenType.PIPE || token.type === TokenType.GT) {\n      return this.parseBlockString(token.type === TokenType.PIPE ? \"literal\" : \"folded\");\n    }\n\n    if (this.isScalar(token)) {\n      if (this.peekAhead(1).type === TokenType.COLON) {\n        return this.parseMapping();\n      }\n      return this.parseScalar();\n    }\n\n    throw this.error(`Unexpected token: ${token.type}`, token);\n  }\n\n  private parseMapping(): { [key: string]: YamlValue } {\n    const result: { [key: string]: YamlValue } = {};\n    const startIndent = this.getCurrentIndent();\n\n    while (true) {\n      this.skipNewlines();\n      const token = this.peek();\n\n      if (token.type === TokenType.EOF || token.type === TokenType.DEDENT) {\n        break;\n      }\n\n      if (!this.isScalar(token)) {\n        break;\n      }\n\n      if (this.peekAhead(1).type !== TokenType.COLON) {\n        break;\n      }\n\n      const key = this.parseScalarAsString();\n      this.expect(TokenType.COLON);\n\n      const afterColon = this.peek();\n\n      if (afterColon.type === TokenType.NEWLINE) {\n        this.advance();\n        this.skipEmptyLines();\n        const nextToken = this.peek();\n\n        if (nextToken.type === TokenType.INDENT) {\n          this.advance();\n          const value = this.parseValue();\n          result[key] = value;\n\n          this.skipNewlines();\n          if (this.peek().type === TokenType.DEDENT) {\n            this.advance();\n          }\n        } else {\n          result[key] = null;\n        }\n      } else if (afterColon.type === TokenType.PIPE || afterColon.type === TokenType.GT) {\n        const value = this.parseBlockString(afterColon.type === TokenType.PIPE ? \"literal\" : \"folded\");\n        result[key] = value;\n      } else if (afterColon.type === TokenType.LBRACKET) {\n        result[key] = this.parseInlineSequence();\n      } else if (afterColon.type === TokenType.LBRACE) {\n        result[key] = this.parseInlineMapping();\n      } else if (this.isScalar(afterColon)) {\n        result[key] = this.parseScalar();\n      } else if (afterColon.type === TokenType.EOF || afterColon.type === TokenType.DEDENT) {\n        result[key] = null;\n      } else {\n        throw this.error(`Unexpected token after colon: ${afterColon.type}`, afterColon);\n      }\n    }\n\n    return result;\n  }\n\n  private parseSequence(): YamlValue[] {\n    const result: YamlValue[] = [];\n\n    while (true) {\n      this.skipNewlines();\n      const token = this.peek();\n\n      if (token.type !== TokenType.DASH) {\n        break;\n      }\n\n      this.advance();\n\n      const afterDash = this.peek();\n\n      if (afterDash.type === TokenType.NEWLINE) {\n        this.advance();\n        this.skipEmptyLines();\n        const nextToken = this.peek();\n\n        if (nextToken.type === TokenType.INDENT) {\n          this.advance();\n          const value = this.parseValue();\n          result.push(value);\n\n          this.skipNewlines();\n          if (this.peek().type === TokenType.DEDENT) {\n            this.advance();\n          }\n        } else {\n          result.push(null);\n        }\n      } else if (afterDash.type === TokenType.LBRACKET) {\n        result.push(this.parseInlineSequence());\n      } else if (afterDash.type === TokenType.LBRACE) {\n        result.push(this.parseInlineMapping());\n      } else if (this.isScalar(afterDash)) {\n        if (this.peekAhead(1).type === TokenType.COLON) {\n          const nestedMapping = this.parseMapping();\n          result.push(nestedMapping);\n        } else {\n          result.push(this.parseScalar());\n        }\n      } else if (afterDash.type === TokenType.EOF || afterDash.type === TokenType.DEDENT) {\n        result.push(null);\n      } else {\n        throw this.error(`Unexpected token after dash: ${afterDash.type}`, afterDash);\n      }\n    }\n\n    return result;\n  }\n\n  private parseInlineSequence(): YamlValue[] {\n    this.expect(TokenType.LBRACKET);\n    const result: YamlValue[] = [];\n\n    while (true) {\n      this.skipInlineWhitespace();\n      const token = this.peek();\n\n      if (token.type === TokenType.RBRACKET) {\n        this.advance();\n        break;\n      }\n\n      if (token.type === TokenType.EOF) {\n        throw this.error(\"Unterminated inline sequence\", token);\n      }\n\n      if (token.type === TokenType.LBRACKET) {\n        result.push(this.parseInlineSequence());\n      } else if (token.type === TokenType.LBRACE) {\n        result.push(this.parseInlineMapping());\n      } else if (this.isScalar(token)) {\n        result.push(this.parseScalar());\n      } else {\n        throw this.error(`Unexpected token in inline sequence: ${token.type}`, token);\n      }\n\n      this.skipInlineWhitespace();\n      const next = this.peek();\n\n      if (next.type === TokenType.COMMA) {\n        this.advance();\n      } else if (next.type !== TokenType.RBRACKET) {\n        throw this.error(`Expected comma or ] but got ${next.type}`, next);\n      }\n    }\n\n    return result;\n  }\n\n  private parseInlineMapping(): { [key: string]: YamlValue } {\n    this.expect(TokenType.LBRACE);\n    const result: { [key: string]: YamlValue } = {};\n\n    while (true) {\n      this.skipInlineWhitespace();\n      const token = this.peek();\n\n      if (token.type === TokenType.RBRACE) {\n        this.advance();\n        break;\n      }\n\n      if (token.type === TokenType.EOF) {\n        throw this.error(\"Unterminated inline mapping\", token);\n      }\n\n      if (!this.isScalar(token)) {\n        throw this.error(`Expected key but got ${token.type}`, token);\n      }\n\n      const key = this.parseScalarAsString();\n      this.expect(TokenType.COLON);\n      this.skipInlineWhitespace();\n\n      const valueToken = this.peek();\n      let value: YamlValue;\n\n      if (valueToken.type === TokenType.LBRACKET) {\n        value = this.parseInlineSequence();\n      } else if (valueToken.type === TokenType.LBRACE) {\n        value = this.parseInlineMapping();\n      } else if (this.isScalar(valueToken)) {\n        value = this.parseScalar();\n      } else if (valueToken.type === TokenType.COMMA || valueToken.type === TokenType.RBRACE) {\n        value = null;\n      } else {\n        throw this.error(`Unexpected token in inline mapping value: ${valueToken.type}`, valueToken);\n      }\n\n      result[key] = value;\n\n      this.skipInlineWhitespace();\n      const next = this.peek();\n\n      if (next.type === TokenType.COMMA) {\n        this.advance();\n      } else if (next.type !== TokenType.RBRACE) {\n        throw this.error(`Expected comma or } but got ${next.type}`, next);\n      }\n    }\n\n    return result;\n  }\n\n  private parseBlockString(style: \"literal\" | \"folded\"): string {\n    this.advance();\n\n    if (this.peek().type !== TokenType.NEWLINE) {\n      throw this.error(\"Expected newline after block indicator\", this.peek());\n    }\n    this.advance();\n\n    const lines: string[] = [];\n    let blockIndent: number | null = null;\n\n    while (this.peek().type !== TokenType.EOF) {\n      if (this.peek().type === TokenType.DEDENT) {\n        break;\n      }\n\n      if (this.peek().type === TokenType.INDENT) {\n        if (blockIndent === null) {\n          this.advance();\n          blockIndent = this.stateStack[this.stateStack.length - 1]?.indent ?? 0;\n        } else {\n          this.advance();\n        }\n      }\n\n      let lineContent = \"\";\n      while (this.peek().type !== TokenType.NEWLINE && this.peek().type !== TokenType.EOF && this.peek().type !== TokenType.DEDENT) {\n        const token = this.peek();\n        if (this.isScalar(token)) {\n          lineContent += token.value;\n          this.advance();\n        } else if (token.type === TokenType.COLON) {\n          lineContent += \":\";\n          this.advance();\n        } else {\n          break;\n        }\n      }\n\n      if (lineContent || this.peek().type === TokenType.NEWLINE) {\n        lines.push(lineContent);\n      }\n\n      if (this.peek().type === TokenType.NEWLINE) {\n        this.advance();\n      } else {\n        break;\n      }\n\n      if (this.peek().type === TokenType.DEDENT) {\n        this.advance();\n        break;\n      }\n    }\n\n    if (style === \"literal\") {\n      return lines.join(\"\\n\");\n    } else {\n      return lines.map(l => l.trim()).join(\" \").trim();\n    }\n  }\n\n  private parseScalar(): YamlValue {\n    const token = this.peek();\n    this.advance();\n\n    switch (token.type) {\n      case TokenType.STRING:\n        return token.value;\n      case TokenType.NUMBER:\n        return parseFloat(token.value);\n      case TokenType.BOOLEAN:\n        return token.value === \"true\";\n      case TokenType.NULL:\n        return null;\n      default:\n        throw this.error(`Expected scalar but got ${token.type}`, token);\n    }\n  }\n\n  private parseScalarAsString(): string {\n    const token = this.peek();\n    this.advance();\n    return token.value;\n  }\n\n  private isScalar(token: Token): boolean {\n    return (\n      token.type === TokenType.STRING ||\n      token.type === TokenType.NUMBER ||\n      token.type === TokenType.BOOLEAN ||\n      token.type === TokenType.NULL\n    );\n  }\n\n  private skipNewlines(): void {\n    while (this.peek().type === TokenType.NEWLINE) {\n      this.advance();\n    }\n  }\n\n  private skipEmptyLines(): void {\n    while (this.peek().type === TokenType.NEWLINE) {\n      this.advance();\n    }\n  }\n\n  private skipInlineWhitespace(): void {\n    while (this.peek().type === TokenType.NEWLINE) {\n      this.advance();\n    }\n  }\n\n  private peek(): Token {\n    return this.tokens[this.pos] || { type: TokenType.EOF, value: \"\", line: 0, column: 0 };\n  }\n\n  private peekAhead(offset: number): Token {\n    return this.tokens[this.pos + offset] || { type: TokenType.EOF, value: \"\", line: 0, column: 0 };\n  }\n\n  private advance(): void {\n    this.pos++;\n  }\n\n  private expect(type: TokenType): void {\n    const token = this.peek();\n    if (token.type !== type) {\n      throw this.error(`Expected ${type} but got ${token.type}`, token);\n    }\n    this.advance();\n  }\n\n  private getCurrentIndent(): number {\n    return this.stateStack[this.stateStack.length - 1]?.indent ?? 0;\n  }\n\n  private error(message: string, token: Token): { message: string; line: number; column: number } {\n    return { message, line: token.line, column: token.column };\n  }\n}\n\n// ============================================================================\n// Main Export\n// ============================================================================\n\n/**\n * Parse YAML content and return a result indicating success or failure.\n * @param content - The YAML string to parse\n * @returns A discriminated union of success (with data) or error (with line number)\n */\nexport function parseYaml(content: string): YamlParseResult {\n  try {\n    const lexer = new Lexer(content);\n    const tokens = lexer.tokenize();\n    const parser = new Parser(tokens);\n    return parser.parse();\n  } catch (err: unknown) {\n    if (typeof err === \"object\" && err !== null && \"message\" in err && \"line\" in err) {\n      const e = err as { message: string; line: number; column?: number };\n      return { success: false, error: e.message, line: e.line, column: e.column };\n    }\n    return { success: false, error: String(err), line: 1 };\n  }\n}\n"
