        "content": "/**\n * CLI entry point for YAML validation.\n * Accepts a file path argument and validates the YAML syntax.\n */\n\nimport { parseYaml } from \"./yaml-parser\";\n\nfunction printUsage(): void {\n  console.log(\"Usage: bun run validate <file-path>\");\n}\n\nasync function fileExists(path: string): Promise<boolean> {\n  try {\n    const file = Bun.file(path);\n    return await file.exists();\n  } catch {\n    return false;\n  }\n}\n\nasync function readFile(path: string): Promise<string> {\n  const file = Bun.file(path);\n  return await file.text();\n}\n\nasync function main(): Promise<void> {\n  const args = process.argv.slice(2);\n\n  if (args.length === 0) {\n    printUsage();\n    process.exit(1);\n  }\n\n  const filePath = args[0];\n\n  if (!(await fileExists(filePath))) {\n    console.error(`Error: File not found: ${filePath}`);\n    process.exit(1);\n  }\n\n  const content = await readFile(filePath);\n  const result = parseYaml(content);\n\n  if (result.success) {\n    console.log(`Valid YAML: ${filePath}`);\n    process.exit(0);\n  } else {\n    console.error(`Syntax error at line ${result.line}: ${result.error}`);\n    process.exit(1);\n  }\n}\n\nmain();\n"
      },
