        "new_string": "  private parseBlockString(style: \"literal\" | \"folded\"): string {\n    this.advance();\n\n    if (this.peek().type !== TokenType.NEWLINE) {\n      throw this.error(\"Expected newline after block indicator\", this.peek());\n    }\n    this.advance();\n\n    const lines: string[] = [];\n    let hasSeenIndent = false;\n\n    while (this.peek().type !== TokenType.EOF) {\n      const token = this.peek();\n\n      if (token.type === TokenType.DEDENT) {\n        this.advance();\n        break;\n      }\n\n      if (token.type === TokenType.INDENT) {\n        hasSeenIndent = true;\n        this.advance();\n        continue;\n      }\n\n      if (token.type === TokenType.NEWLINE) {\n        if (hasSeenIndent) {\n          lines.push(\"\");\n        }\n        this.advance();\n        continue;\n      }\n\n      let lineContent = \"\";\n      while (this.peek().type !== TokenType.NEWLINE && this.peek().type !== TokenType.EOF && this.peek().type !== TokenType.DEDENT) {\n        const tok = this.peek();\n        if (this.isScalar(tok)) {\n          lineContent += tok.value;\n          this.advance();\n        } else if (tok.type === TokenType.COLON) {\n          lineContent += \":\";\n          this.advance();\n        } else if (tok.type === TokenType.DASH) {\n          lineContent += \"-\";\n          this.advance();\n        } else {\n          break;\n        }\n      }\n\n      if (lineContent) {\n        lines.push(lineContent);\n      }\n\n      if (this.peek().type === TokenType.NEWLINE) {\n        this.advance();\n      }\n\n      if (this.peek().type === TokenType.DEDENT) {\n        this.advance();\n        break;\n      }\n    }\n\n    if (style === \"literal\") {\n      return lines.join(\"\\n\");\n    } else {\n      return lines.map(l => l.trim()).join(\" \").trim();\n    }\n  }"
