/**
 * Parse YAML content and return a result indicating success or failure.
 * @param content - The YAML string to parse
 * @returns A discriminated union of success (with data) or error (with line number)
 */
export function parseYaml(content: string): YamlParseResult {
  try {
    const lexer = new Lexer(content);
    const tokens = lexer.tokenize();
    const parser = new Parser(tokens);
    return parser.parse();
  } catch (err: unknown) {
    if (typeof err === "object" && err !== null && "message" in err && "line" in err) {
      const e = err as { message: string; line: number; column?: number };
      return { success: false, error: e.message, line: e.line, column: e.column };
    }
    return { success: false, error: String(err), line: 1 };
  }
}

import { describe, expect, test } from "bun:test";
import { parseYaml, type YamlParseResult } from "./yaml-parser";

describe("yaml-parser", () => {
  describe("empty and null values", () => {
    test("empty string returns null", () => {
      const result = parseYaml("");
      expect(result.success).toBe(true);
      if (result.success) {
        expect(result.data).toBeNull();
      }
    });

    test("whitespace only returns null", () => {
      const result = parseYaml("   \n   \n   ");
      expect(result.success).toBe(true);
      if (result.success) {
        expect(result.data).toBeNull();
      }
    });
  });

  describe("simple key-value pairs", () => {
    test("simple key-value", () => {
      const result = parseYaml("key: value");
      expect(result.success).toBe(true);
      if (result.success) {
        expect(result.data).toEqual({ key: "value" });
      }
    });

    test("multiple key-value pairs", () => {
      const result = parseYaml("name: Alice\nage: 30");
      expect(result.success).toBe(true);
      if (result.success) {
        expect(result.data).toEqual({ name: "Alice", age: 30 });
      }
    });
  });

  describe("nested mappings", () => {
    test("nested mapping", () => {
      const result = parseYaml("a:\n  b: c");
      expect(result.success).toBe(true);
      if (result.success) {
        expect(result.data).toEqual({ a: { b: "c" } });
      }
    });

    test("deeply nested mapping", () => {
      const result = parseYaml("level1:\n  level2:\n    level3: deep");
      expect(result.success).toBe(true);
      if (result.success) {
        expect(result.data).toEqual({ level1: { level2: { level3: "deep" } } });
      }
    });
  });

  describe("sequences", () => {
    test("simple sequence", () => {
      const result = parseYaml("- a\n- b");
      expect(result.success).toBe(true);
      if (result.success) {
        expect(result.data).toEqual(["a", "b"]);
      }
    });

    test("sequence with numbers", () => {
      const result = parseYaml("- 1\n- 2\n- 3");
      expect(result.success).toBe(true);
      if (result.success) {
        expect(result.data).toEqual([1, 2, 3]);
      }
    });

    test("mixed nesting - mapping with sequence", () => {
      const result = parseYaml("items:\n  - a\n  - b");
      expect(result.success).toBe(true);
      if (result.success) {
        expect(result.data).toEqual({ items: ["a", "b"] });
      }
    });

    test("sequence of mappings", () => {
      const result = parseYaml("- name: Alice\n- name: Bob");
      expect(result.success).toBe(true);
      if (result.success) {
        expect(result.data).toEqual([{ name: "Alice" }, { name: "Bob" }]);
      }
    });
  });

  describe("quoted strings", () => {
    test("double quoted string", () => {
      const result = parseYaml('key: "val: ue"');
      expect(result.success).toBe(true);
      if (result.success) {
        expect(result.data).toEqual({ key: "val: ue" });
      }
    });

    test("single quoted string", () => {
      const result = parseYaml("key: 'value with spaces'");
      expect(result.success).toBe(true);
      if (result.success) {
        expect(result.data).toEqual({ key: "value with spaces" });
      }
    });

    test("escaped characters in double quotes", () => {
      const result = parseYaml('key: "line1\\nline2"');
      expect(result.success).toBe(true);
      if (result.success) {
        expect(result.data).toEqual({ key: "line1\nline2" });
      }
    });
  });

  describe("numbers", () => {
    test("integer", () => {
      const result = parseYaml("count: 42");
      expect(result.success).toBe(true);
      if (result.success) {
        expect(result.data).toEqual({ count: 42 });
      }
    });

    test("negative number", () => {
      const result = parseYaml("temp: -10");
      expect(result.success).toBe(true);
      if (result.success) {
        expect(result.data).toEqual({ temp: -10 });
      }
    });

    test("float", () => {
      const result = parseYaml("pi: 3.14");
      expect(result.success).toBe(true);
      if (result.success) {
        expect(result.data).toEqual({ pi: 3.14 });
      }
    });
  });

  describe("booleans", () => {
    test("true", () => {
      const result = parseYaml("flag: true");
      expect(result.success).toBe(true);
      if (result.success) {
        expect(result.data).toEqual({ flag: true });
      }
    });

    test("false", () => {
      const result = parseYaml("enabled: false");
      expect(result.success).toBe(true);
      if (result.success) {
        expect(result.data).toEqual({ enabled: false });
      }
    });
  });

  describe("null values", () => {
    test("null keyword", () => {
      const result = parseYaml("value: null");
      expect(result.success).toBe(true);
      if (result.success) {
        expect(result.data).toEqual({ value: null });
      }
    });

    test("tilde for null", () => {
      const result = parseYaml("value: ~");
      expect(result.success).toBe(true);
      if (result.success) {
        expect(result.data).toEqual({ value: null });
      }
    });
  });

  describe("comments", () => {
    test("comment line is ignored", () => {
      const result = parseYaml("# comment\nkey: val");
      expect(result.success).toBe(true);
      if (result.success) {
        expect(result.data).toEqual({ key: "val" });
      }
    });

    test("inline comment", () => {
      const result = parseYaml("key: val # inline comment");
      expect(result.success).toBe(true);
      if (result.success) {
        expect(result.data).toEqual({ key: "val" });
      }
    });

    test("multiple comments", () => {
      const result = parseYaml("# first\n# second\nkey: val\n# third");
      expect(result.success).toBe(true);
      if (result.success) {
        expect(result.data).toEqual({ key: "val" });
      }
    });
  });

  describe("inline sequences", () => {
    test("inline array", () => {
      const result = parseYaml("items: [a, b, c]");
      expect(result.success).toBe(true);
      if (result.success) {
        expect(result.data).toEqual({ items: ["a", "b", "c"] });
      }
    });

    test("inline array with numbers", () => {
      const result = parseYaml("nums: [1, 2, 3]");
      expect(result.success).toBe(true);
      if (result.success) {
        expect(result.data).toEqual({ nums: [1, 2, 3] });
      }
    });

    test("empty inline array", () => {
      const result = parseYaml("items: []");
      expect(result.success).toBe(true);
      if (result.success) {
        expect(result.data).toEqual({ items: [] });
      }
    });
  });

  describe("inline mappings", () => {
    test("inline object", () => {
      const result = parseYaml("obj: {a: 1}");
      expect(result.success).toBe(true);
      if (result.success) {
        expect(result.data).toEqual({ obj: { a: 1 } });
      }
    });

    test("inline object with multiple keys", () => {
      const result = parseYaml("obj: {x: 1, y: 2}");
      expect(result.success).toBe(true);
      if (result.success) {
        expect(result.data).toEqual({ obj: { x: 1, y: 2 } });
      }
    });

    test("empty inline object", () => {
      const result = parseYaml("obj: {}");
      expect(result.success).toBe(true);
      if (result.success) {
        expect(result.data).toEqual({ obj: {} });
      }
    });
  });

  describe("multi-line strings", () => {
    test("literal block scalar with pipe", () => {
      const result = parseYaml("text: |\n  line1\n  line2");
      expect(result.success).toBe(true);
      if (result.success) {
        expect(result.data).toEqual({ text: "line1\nline2" });
      }
    });

    test("folded block scalar with gt", () => {
      const result = parseYaml("text: >\n  line1\n  line2");
      expect(result.success).toBe(true);
      if (result.success) {
        expect(result.data).toEqual({ text: "line1 line2" });
      }
    });
  });

  describe("error cases", () => {
    test("invalid: bad indent", () => {
      const result = parseYaml("a:\nb: c");
      expect(result.success).toBe(false);
      if (!result.success) {
        expect(result.line).toBeGreaterThan(0);
      }
    });

    test("invalid: unclosed double quote", () => {
      const result = parseYaml('key: "value');
      expect(result.success).toBe(false);
      if (!result.success) {
        expect(result.line).toBe(1);
        expect(result.error).toContain("Unterminated");
      }
    });

    test("invalid: unclosed single quote", () => {
      const result = parseYaml("key: 'value");
      expect(result.success).toBe(false);
      if (!result.success) {
        expect(result.line).toBe(1);
        expect(result.error).toContain("Unterminated");
      }
    });

    test("invalid: tabs in indentation", () => {
      const result = parseYaml("key:\n\tvalue: bad");
      expect(result.success).toBe(false);
      if (!result.success) {
        expect(result.error.toLowerCase()).toContain("tab");
      }
    });

    test("invalid: unclosed inline sequence", () => {
      const result = parseYaml("items: [a, b");
      expect(result.success).toBe(false);
      if (!result.success) {
        expect(result.error).toContain("Unterminated");
      }
    });

    test("invalid: unclosed inline mapping", () => {
      const result = parseYaml("obj: {a: 1");
      expect(result.success).toBe(false);
      if (!result.success) {
        expect(result.error).toContain("Unterminated");
      }
    });
  });

  describe("complex structures", () => {
    test("complex nested structure", () => {
      const yaml = `
server:
  host: localhost
  port: 8080
database:
  name: mydb
  credentials:
    user: admin
    pass: secret
`;
      const result = parseYaml(yaml);
      expect(result.success).toBe(true);
      if (result.success) {
        expect(result.data).toEqual({
          server: { host: "localhost", port: 8080 },
          database: { name: "mydb", credentials: { user: "admin", pass: "secret" } },
        });
      }
    });

    test("array of objects", () => {
      const yaml = `
users:
  - name: Alice
    age: 30
  - name: Bob
    age: 25
`;
      const result = parseYaml(yaml);
      expect(result.success).toBe(true);
      if (result.success) {
        expect(result.data).toEqual({
          users: [
            { name: "Alice", age: 30 },
            { name: "Bob", age: 25 },
          ],
        });
      }
    });
  });
});

