const yaml = `- name: Alice
  age: 30`;

class Lexer {
  input;
  pos = 0;
  line = 1;
  column = 1;
  indentStack = [0];
  tokens = [];
  atLineStart = true;

  constructor(input) {
    this.input = input;
  }

  tokenize() {
    while (this.pos < this.input.length) {
      if (this.atLineStart) {
        this.handleIndentation();
        this.atLineStart = false;
      }

      const char = this.peek();

      if (char === "\n") {
        this.addToken("NEWLINE", "\n");
        this.advance();
        this.atLineStart = true;
        continue;
      }

      if (char === " ") {
        this.advance();
        continue;
      }

      if (char === ":") {
        this.advance();
        if (this.peek() === " " || this.peek() === "\n" || this.pos >= this.input.length) {
          this.addToken("COLON", ":");
        }
        continue;
      }

      if (char === "-") {
        const next = this.peekAhead(1);
        if (next === " " || next === "\n" || this.pos + 1 >= this.input.length) {
          this.addToken("DASH", "-");
          this.advance();
          continue;
        }
      }

      this.readUnquotedValue();
    }

    while (this.indentStack.length > 1) {
      this.indentStack.pop();
      this.addToken("DEDENT", "");
    }

    this.addToken("EOF", "");
    return this.tokens;
  }

  handleIndentation() {
    let indent = 0;
    while (this.peek() === " ") {
      indent++;
      this.advance();
    }

    if (this.peek() === "\n" || this.peek() === "#") {
      return;
    }

    if (this.pos >= this.input.length) {
      return;
    }

    const currentIndent = this.indentStack[this.indentStack.length - 1];

    if (indent > currentIndent) {
      this.indentStack.push(indent);
      this.addToken("INDENT", "");
    } else if (indent < currentIndent) {
      while (this.indentStack.length > 1 && this.indentStack[this.indentStack.length - 1] > indent) {
        this.indentStack.pop();
        this.addToken("DEDENT", "");
      }
    }
  }

  readUnquotedValue() {
    const startLine = this.line;
    const startColumn = this.column;
    let value = "";

    while (this.pos < this.input.length) {
      const char = this.peek();
      if (char === ":" && (this.peekAhead(1) === " " || this.peekAhead(1) === "\n" || this.pos + 1 >= this.input.length)) {
        break;
      }
      if (char === "\n" || char === "#" || char === "," || char === "]" || char === "}") {
        break;
      }
      value += char;
      this.advance();
    }

    value = value.trimEnd();
    if (value) {
      this.tokens.push({ type: "STRING", value, line: startLine, column: startColumn });
    }
  }

  peek() {
    return this.input[this.pos] || "";
  }

  peekAhead(offset) {
    return this.input[this.pos + offset] || "";
  }

  advance() {
    if (this.peek() === "\n") {
      this.line++;
      this.column = 1;
    } else {
      this.column++;
    }
    this.pos++;
  }

  addToken(type, value) {
    this.tokens.push({ type, value, line: this.line, column: this.column });
  }
}

