rue\n  },\n\n  // Invalid YAML cases - indentation errors\n  {\n    name: 'Invalid indentation - inconsistent',\n    yaml: `person:\n  name: John\n   age: 30`,\n    expectValid: false,\n    expectedErrors: ['indentation']\n  },\n  {\n    name: 'Tab character',\n    yaml: `name: John\n\\tage: 30`,\n    expectValid: false,\n    expectedErrors: ['Tabs']\n  },\n\n  // Invalid YAML cases - unterminated strings\n  {\n    name: 'Unterminated single quote',\n    yaml: `name: 'John\nage: 30`,\n    expectValid: false,\n    expectedErrors: ['Unterminated']\n  },\n  {\n    name: 'Unterminated double quote',\n    yaml: `name: \"John\nage: 30`,\n    expectValid: false,\n    expectedErrors: ['Unterminated']\n  },\n\n  // Invalid YAML cases - malformed keys\n  {\n    name: 'Key starting with @',\n    yaml: `@invalid: value`,\n    expectValid: false,\n    expectedErrors: ['Invalid key']\n  },\n\n  // Invalid YAML cases - structural errors\n  {\n    name: 'Unclosed brace',\n    yaml: `person: {name: John`,\n    expectValid: false,\n    expectedErrors: ['Unclosed']\n  },\n  {\n    name: 'Unclosed bracket',\n    yaml: `items: [1, 2, 3`,\n    expectValid: false,\n    expectedErrors: ['Unclosed']\n  },\n  {\n    name: 'Double colon typo',\n    yaml: `name:: John`,\n    expectValid: false,\n    expectedErrors: ['double colon']\n  }\n];\n\n// Run tests\nconsole.log('=== Inline YAML Validator Test Results ===\\n');\n\nlet passed = 0;\nlet failed = 0;\n\nfor (const test of testCases) {\n  const result = validateYAML(test.yaml);\n  const testPassed = result.valid === test.expectValid;\n\n  if (testPassed && !test.expectValid && test.expectedErrors) {\n    // Check if expected error types were found\n    const foundExpectedErrors = test.expectedErrors.every(expected =>\n      result.errors.some(e => e.message.includes(expected))\n    );\n    if (!foundExpectedErrors) {\n      console.log(`PARTIAL: ${test.name}`);\n      console.log(`  Expected errors containing: ${test.expectedErrors.join(', ')}`);\n      console.log(`  Got: ${result.errors.map(e => e.message).join('; ')}`);\n      failed++;\n      continue;\n    }\n  }\n\n  if (testPassed) {\n    console.log(`PASS: ${test.name}`);\n    passed++;\n  } else {\n    console.log(`FAIL: ${test.name}`);\n    console.log(`  Expected valid: ${test.expectValid}, Got valid: ${result.valid}`);\n    if (result.errors.length > 0) {\n      console.log(`  Errors: ${result.errors.map(e => `Line ${e.line}: ${e.message}`).join('; ')}`);\n    }\n    failed++;\n  }\n}\n\nconsole.log(`\\n=== Summary ===`);\nconsole.log(`Passed: ${passed}/${testCases.length}`);\nconsole.log(`Failed: ${failed}/${testCases.length}`);\nconsole.log(`Success Rate: ${((passed / testCases.length) * 100).toFixed(1)}%`);\n\n// Additional edge case tests\nconsole.log('\\n=== Edge Case Analysis ===\\n');\n\n// Test case: Valid YAML that might trigger false positives\nconst edgeCases = [\n  {\n    name: 'URL with colon',\n    yaml: `website: https://example.com`,\n    expectValid: true\n  },\n  {\n    name: 'Colon in quoted string',\n    yaml: `time: \"10:30:00\"`,\n    expectValid: true\n  },\n  {\n    name: 'Complex nested with mixed types',\n    yaml: `config:\n  database:\n    host: localhost\n    port: 5432\n  features:\n    - name: auth\n      enabled: true\n    - name: cache\n      enabled: false`,\n    expectValid: true\n  },\n  {\n    name: 'Anchor and alias (YAML 1.1 feature)',\n    yaml: `defaults: &defaults\n  adapter: postgres\ndevelopment:\n  <<: *defaults\n  database: dev_db`,\n    expectValid: true\n  }\n];\n\nconsole.log('Edge cases (checking for false positives):');\nfor (const test of edgeCases) {\n  const result = validateYAML(test.yaml);\n  if (result.valid === test.expectValid) {\n    console.log(`  OK: ${test.name}`);\n  } else {\n    console.log(`  FALSE POSITIVE: ${test.name}`);\n    console.log(`    Errors: ${result.errors.map(e => e.message).join('; ')}`);\n  }\n}\n\n// Summary output for hypothesis validation\nconsole.log('\\n