e.line,\n      column: 1,\n      message: \"Inconsistent indentation: mixed tabs and spaces in the same line\",\n    };\n  }\n\n  if (usesSpaces === true && hasTabs) {\n    return {\n      line: state.line,\n      column: 1,\n      message: \"Inconsistent indentation: file uses spaces but this line uses tabs\",\n    };\n  }\n\n  if (usesTabs === true && hasSpaces && usesSpaces !== true) {\n    return {\n      line: state.line,\n      column: 1,\n      message: \"Inconsistent indentation: file uses tabs but this line uses spaces\",\n    };\n  }\n\n  return null;\n}\n\nfunction validateStrings(line: string, state: ParserState): YamlError | null {\n  let inSingleQuote = false;\n  let inDoubleQuote = false;\n  let escaped = false;\n\n  for (let i = 0; i < line.length; i++) {\n    const char = line[i];\n\n    if (escaped) {\n      escaped = false;\n      continue;\n    }\n\n    if (char === \"\\\\\" && inDoubleQuote) {\n      escaped = true;\n      continue;\n    }\n\n    if (char === \"#\" && !inSingleQuote && !inDoubleQuote) {\n      break;\n    }\n\n    if (char === \"'\" && !inDoubleQuote) {\n      if (inSingleQuote && line[i + 1] === \"'\") {\n        i++;\n        continue;\n      }\n      inSingleQuote = !inSingleQuote;\n    } else if (char === '\"' && !inSingleQuote) {\n      inDoubleQuote = !inDoubleQuote;\n    }\n  }\n\n  if (inSingleQuote) {\n    const col = line.indexOf(\"'\") + 1;\n    return {\n      line: state.line,\n      column: col,\n      message: \"Unterminated string: missing closing single quote\",\n    };\n  }\n\n  if (inDoubleQuote) {\n    const col = line.indexOf('\"') + 1;\n    return {\n      line: state.line,\n      column: col,\n      message: \"Unterminated string: missing closing double quote\",\n    };\n  }\n\n  return null;\n}\n\nfunction validateListItem(\n  line: string,\n  trimmed: string,\n  state: ParserState,\n  _currentIndent: number\n): YamlError | null {\n  const dashIndex = line.indexOf(\"-\");\n\n  if (dashIndex >= 0 && dashIndex < line.length - 1) {\n    const afterDash = line[dashIndex + 1];\n\n    if (afterDash !== \" \" && afterDash !== \"\\t\" && trimmed !== \"-\") {\n      const invalidPattern = line.substring(dashIndex).match(/^-[^\\s]/);\n      if (invalidPattern) {\n        return {\n          line: state.line,\n          column: dashIndex + 1,\n          message: \"Invalid list item: dash must be followed by a space\",\n        };\n      }\n    }\n  }\n\n  return null;\n}\n\nfunction isKeyValueLine(trimmed: string): boolean {\n  if (trimmed.startsWith(\"- \") || trimmed === \"-\") {\n    return false;\n  }\n\n  const colonIndex = findUnquotedColon(trimmed);\n  return colonIndex > 0;\n}\n\nfunction findUnquotedColon(str: string): number {\n  let inSingleQuote = false;\n  let inDoubleQuote = false;\n  let escaped = false;\n\n  for (let i = 0; i < str.length; i++) {\n    const char = str[i];\n\n    if (escaped) {\n      escaped = false;\n      continue;\n    }\n\n    if (char === \"\\\\\" && inDoubleQuote) {\n      escaped = true;\n      continue;\n    }\n\n    if (char === \"'\" && !inDoubleQuote) {\n      if (inSingleQuote && str[i + 1] === \"'\") {\n        i++;\n        continue;\n      }\n      inSingleQuote = !inSingleQuote;\n    } else if (char === '\"' && !inSingleQuote) {\n      inDoubleQuote = !inDoubleQuote;\n    } else if (char === \":\" && !inSingleQuote && !inDoubleQuote) {\n      if (i + 1 >= str.length || str[i + 1] === \" \" || str[i + 1] === \"\\t\" || str[i + 1] === \"\\n\") {\n        return i;\n      }\n    }\n  }\n\n  return -1;\n}\n\nfunction extractKey(trimmed: string): string | null {\n  const colonIndex = findUnquotedColon(trimmed);\n  if (colonIndex <= 0) return null;\n\n  let key = trimmed.substring(0, colonIndex).trim();\n\n  if ((key.startsWith('\"') && key.endsWith('\"')) || (key.startsWith(\"'\") && key.endsWith(\"'\"))) {\n    key = key.slice(1, -1);\n  }\n\n  return key;\n}\n\nfunction validateKey(\n  line: string,\n  trimmed: string,\n  state: ParserState,\n  keyTrackers: KeyTracker[],\n  currentIndent: number\n): YamlError | null {\n  const key = extractKey(trimmed);\n\n  if (key === null || key.length === 0) {\n    const colonIndex = line.indexOf(\":\");\n    if (colonIndex >= 0) {\n      return {\n        line: state.line,\n        column: colonIndex + 1,\n        message: \"Invalid key syntax: empty or malformed key before colon\",\n      };\n    }\n    return null;\n  }\n\n  if (!/^[\\w\\s\\-_.'\"[\\]{}()@$%^&*+=<>?/\\\\|~`!]+$/i.test(key) && !key.startsWith('\"') && !key.startsWith(\"'\")) {\n    const colonIndex = line.indexOf(\":\");\n    return {\n      line: state.line,\n      column: colonIndex + 1,\n      message: `Invalid key syntax: key contains invalid characters`,\n    };\n  }\n\n  let tracker = keyTrackers.find((t) => t.indent === currentIndent);\n  if (!tracker) {\n    tracker = { indent: currentIndent, keys: new Set() };\n    keyTrackers.push(tracker);\n  } else if (tracker.indent === currentIndent) {\n    if (tracker.keys.has(key)) {\n      const colonIndex = line.indexOf(\":\");\n      return {\n        line: state.line,\n        column: colonIndex - key.length + 1,\n        message: `Duplicate key: \"${key}\" already defined at this indentation level`,\n      };\n    }\n  }\n\n  tracker.keys.add(key);\n\n  return null;\n}\n\nfunction checkMultilineIndicator(trimmed: string): string | null {\n  const colonIndex = findUnquotedColon(trimmed);\n  if (colonIndex < 0) return null;\n\n  const afterColon = trimmed.substring(colonIndex + 1).trim();\n\n  if (afterColon === \"|\" || afterColon === \"|-\" || afterColon === \"|+\") {\n    return \"|\";\n  }\n  if (afterColon === \">\" || afterColon === \">-\" || afterColon === \">+\") {\n    return \">\";\n  }\n\n  return null;\n}\n"
