idateYaml(\"parent:\\n  key: value1\\nkey: value2\\n\");\ntest(\"Same key at different levels is valid\", r10.valid === true);\n\n// Test 11: Multi-document YAML (BR-004)\nconst r11 = validateMultiDocYaml(\"doc1: a\\n---\\ndoc2: b\\n\");\ntest(\"Multi-document YAML\", r11.valid === true);\n\n// Test 12: Nested structure\nconst r12 = validateYaml(\"parent:\\n  child1: value1\\n  child2: value2\\n\");\ntest(\"Nested structure\", r12.valid === true);\n\n// Test 13: Multiline strings (literal)\nconst r13 = validateYaml(\"description: |\\n  This is a\\n  multiline string\\n\");\ntest(\"Multiline literal strings\", r13.valid === true);\n\n// Test 14: Multiline strings (folded)\nconst r14 = validateYaml(\"description: >\\n  This is a\\n  folded string\\n\");\ntest(\"Multiline folded strings\", r14.valid === true);\n\n// Test 15: Comments\nconst r15 = validateYaml(\"# This is a comment\\nkey: value # inline comment\\n\");\ntest(\"Comments handled\", r15.valid === true);\n\n// Test 16: Content after document end marker\nconst r16 = validateMultiDocYaml(\"doc1: a\\n...\\nsome_content: b\\n\");\ntest(\"Content after doc end detected\", r16.valid === false && r16.errors[0].message.includes(\"document end marker\"));\n\n// Test 17: Document markers valid usage\nconst r17 = validateMultiDocYaml(\"---\\ndoc1: a\\n...\\n---\\ndoc2: b\\n\");\ntest(\"Document markers valid usage\", r17.valid === true);\n\n// Test 18: Line numbers in errors\nconst r18 = validateYaml(\"line1: ok\\nline2: ok\\nline3: \\\"unterminated\\n\");\ntest(\"Line numbers accurate\", r18.errors[0]?.line === 3);\n\n// Test 19: Column numbers in errors\nconst r19 = validateYaml(\"key: \\\"unterminated\\n\");\ntest(\"Column numbers accurate\", r19.errors[0]?.column > 0);\n\n// Test 20: Valid quoted keys\nconst r20 = validateYaml(\"\\\"quoted key\\\": value\\n\");\ntest(\"Quoted keys valid\", r20.valid === true);\n\n// Test 21: Complex nested structure\nconst r21 = validateYaml(`\ndatabase:\n  host: localhost\n  port: