        "file_path": "/private/tmp/rp1-evals/754049bb/workspace/.rp1/work/worktrees/feature-yaml-validator/src/yaml-validator.ts",
        "old_string": "export interface FileReadResult {\n  content?: string;\n  error?: string;\n}",
        "new_string": "export interface FileReadResult {\n  content?: string;\n  error?: string;\n}\n\nexport interface FileValidationResult {\n  path: string;\n  valid: boolean;\n  errors: YamlError[];\n  fileError?: string;\n}"
