        "file_path": "/private/tmp/rp1-evals/754049bb/workspace/.rp1/work/worktrees/feature-yaml-validator/src/yaml-validator.test.ts",
        "content": "/**\n * Comprehensive tests for YAML Validator\n *\n * COVERAGE LIMITATIONS:\n * The inline YAML parser catches approximately 11% of errors that js-yaml would catch.\n * These tests validate the implemented syntax checks, not full YAML spec compliance.\n *\n * Tests cover:\n * - yaml-parser.ts: validateYaml, validateMultiDocYaml\n * - yaml-validator.ts: parseArgs, readYamlFile, formatError, formatFileError, resolveGlob\n * - Integration: CLI behavior with exit codes\n */\n\nimport { describe, expect, test, beforeAll, afterAll } from \"bun:test\";\nimport { validateYaml, validateMultiDocYaml } from \"./yaml-parser\";\nimport {\n  parseArgs,\n  readYamlFile,\n  formatError,\n  formatFileError,\n  resolveGlob,\n  resolveFiles,\n  validateFiles,\n} from \"./yaml-validator\";\nimport { mkdir, writeFile, rm } from \"node:fs/promises\";\nimport { join } from \"node:path\";\n\n// ============================================================================\n// Test Fixtures Setup\n// ============================================================================\n\nconst TEST_FIXTURES_DIR = join(process.cwd(), \"test-fixtures\");\n\nconst VALID_YAML = `name: test\nversion: 1.0.0\nconfig:\n  host: localhost\n  port: 8080\n`;\n\nconst VALID_YAML_WITH_LIST = `items:\n  - name: item1\n    value: 1\n  - name: item2\n    value: 2\n`;\n\nconst INVALID_YAML_UNTERMINATED_STRING = `name: \"unclosed string\nversion: 1.0.0\n`;\n\nconst INVALID_YAML_MIXED_INDENT = `name: test\nconfig:\n  host: localhost\n\\tport: 8080\n`;\n\nconst INVALID_YAML_DUPLICATE_KEY = `name: test\nname: duplicate\nversion: 1.0.0\n`;\n\nconst INVALID_YAML_LIST_NO_SPACE = `items:\n  -item1\n  - item2\n`;\n\nconst MULTI_DOC_YAML = `doc1: value1\n---\ndoc2: value2\n---\ndoc3: value3\n`;\n\nconst MULTI_DOC_WITH_END = `doc1: value1\n...\n---\ndoc2: value2\n`;\n\nbeforeAll(async () => {\n  await mkdir(TEST_FIXTURES_DIR, { recursive: true });\n  await mkdir(join(TEST_FIXTURES_DIR, \"subdir\"), { recursive: true });\n\n  await writeFile(join(TEST_FIXTURES_DIR, \"valid.yaml\"), VALID_YAML);\n  await writeFile(join(TEST_FIXTURES_DIR, \"valid-list.yml\"), VALID_YAML_WITH_LIST);\n  await writeFile(join(TEST_FIXTURES_DIR, \"invalid-string.yaml\"), INVALID_YAML_UNTERMINATED_STRING);\n  await writeFile(join(TEST_FIXTURES_DIR, \"invalid-indent.yaml\"), INVALID_YAML_MIXED_INDENT);\n  await writeFile(join(TEST_FIXTURES_DIR, \"multi-doc.yaml\"), MULTI_DOC_YAML);\n  await writeFile(join(TEST_FIXTURES_DIR, \"subdir\", \"nested.yaml\"), VALID_YAML);\n  await writeFile(join(TEST_FIXTURES_DIR, \"not-yaml.txt\"), \"This is not YAML\");\n});\n\nafterAll(async () => {\n  await rm(TEST_FIXTURES_DIR, { recursive: true, force: true });\n});\n\n// ============================================================================\n// yaml-parser.ts: validateYaml\n// ============================================================================\n\ndescribe(\"yaml-parser\", () => {\n  describe(\"validateYaml\", () => {\n    test(\"valid simple YAML returns no errors\", () => {\n      const result = validateYaml(\"key: value\\n\");\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"valid YAML with nested structure returns no errors\", () => {\n      const result = validateYaml(VALID_YAML);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"valid YAML with list items returns no errors\", () => {\n      const result = validateYaml(VALID_YAML_WITH_LIST);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"empty file is valid (BR-002)\", () => {\n      const result = validateYaml(\"\");\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"whitespace-only file is valid (BR-002)\", () => {\n      const result = validateYaml(\"   \\n  \\n\");\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"comments-only file is valid\", () => {\n      const result = validateYaml(\"# This is a comment\\n# Another comment\\n\");\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"unterminated double quote string reports error\", () => {\n      const yaml = 'key: \"unclosed\\n';\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.errors.length).toBeGreaterThan(0);\n      expect(result.errors[0].message).toContain(\"Unterminated\");\n    });\n\n    test(\"unterminated single quote string reports error\", () => {\n      const yaml = \"key: 'unclosed\\n\";\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.errors.length).toBeGreaterThan(0);\n      expect(result.errors[0].message).toContain(\"Unterminated\");\n    });\n\n    test(\"mixed tabs and spaces in same line reports error\", () => {\n      const yaml = \" \\tkey: value\\n\";\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.errors[0].message).toContain(\"mixed tabs and spaces\");\n    });\n\n    test(\"inconsistent indentation (file uses spaces, line uses tabs) reports error\", () => {\n      const result = validateYaml(INVALID_YAML_MIXED_INDENT);\n      expect(result.valid).toBe(false);\n      expect(result.errors.length).toBeGreaterThan(0);\n      expect(result.errors[0].message).toContain(\"tabs\");\n    });\n\n    test(\"duplicate key at same level reports error\", () => {\n      const result = validateYaml(INVALID_YAML_DUPLICATE_KEY);\n      expect(result.valid).toBe(false);\n      expect(result.errors.length).toBeGreaterThan(0);\n      expect(result.errors[0].message).toContain(\"Duplicate key\");\n    });\n\n    test(\"invalid list item (no space after dash) reports error\", () => {\n      const result = validateYaml(INVALID_YAML_LIST_NO_SPACE);\n      expect(result.valid).toBe(false);\n      expect(result.errors.length).toBeGreaterThan(0);\n      expect(result.errors[0].message).toContain(\"dash must be followed by a space\");\n    });\n\n    test(\"error includes correct line number\", () => {\n      const yaml = \"line1: ok\\nline2: ok\\nline3: \\\"unclosed\\n\";\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.errors[0].line).toBe(3);\n    });\n\n    test(\"error includes column number\", () => {\n      const yaml = 'key: \"unclosed\\n';\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.errors[0].column).toBeGreaterThan(0);\n    });\n\n    test(\"multiline string indicator (|) is valid\", () => {\n      const yaml = \"description: |\\n  This is a\\n  multiline string\\n\";\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"multiline string indicator (>) is valid\", () => {\n      const yaml = \"description: >\\n  This is a\\n  folded string\\n\";\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"quoted keys are valid\", () => {\n      const yaml = '\"quoted-key\": value\\n';\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"escaped quotes in strings are handled\", () => {\n      const yaml = 'key: \"value with \\\\\"escaped\\\\\" quotes\"\\n';\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n  });\n\n  describe(\"validateMultiDocYaml\", () => {\n    test(\"multi-document YAML is supported (BR-004)\", () => {\n      const yaml = \"doc1: a\\n---\\ndoc2: b\\n\";\n      const result = validateMultiDocYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"multiple documents with --- separator are valid\", () => {\n      const result = validateMultiDocYaml(MULTI_DOC_YAML);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"document end marker (...) followed by new document is valid\", () => {\n      const result = validateMultiDocYaml(MULTI_DOC_WITH_END);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"content after ... without --- reports error\", () => {\n      const yaml = \"doc1: value\\n...\\ncontent: without_marker\\n\";\n      const result = validateMultiDocYaml(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.errors[0].message).toContain(\"document end marker\");\n    });\n\n    test(\"error in second document reports correct line number\", () => {\n      const yaml = \"doc1: ok\\n---\\nkey: \\\"unclosed\\n\";\n      const result = validateMultiDocYaml(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.errors[0].line).toBe(3);\n    });\n\n    test(\"empty multi-document file is valid\", () => {\n      const yaml = \"---\\n---\\n\";\n      const result = validateMultiDocYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n  });\n});\n\n// ============================================================================\n// yaml-validator.ts: parseArgs\n// ============================================================================\n\ndescribe(\"yaml-validator\", () => {\n  describe(\"parseArgs\", () => {\n    test(\"parses file arguments\", () => {\n      const result = parseArgs([\"file1.yaml\", \"file2.yaml\"]);\n      expect(result.files).toEqual([\"file1.yaml\", \"file2.yaml\"]);\n      expect(result.quiet).toBe(false);\n      expect(result.help).toBe(false);\n    });\n\n    test(\"parses -q flag for quiet mode\", () => {\n      const result = parseArgs([\"-q\", \"file.yaml\"]);\n      expect(result.quiet).toBe(true);\n      expect(result.files).toEqual([\"file.yaml\"]);\n    });\n\n    test(\"parses --quiet flag for quiet mode\", () => {\n      const result = parseArgs([\"--quiet\", \"file.yaml\"]);\n      expect(result.quiet).toBe(true);\n      expect(result.files).toEqual([\"file.yaml\"]);\n    });\n\n    test(\"parses -h flag for help\", () => {\n      const result = parseArgs([\"-h\"]);\n      expect(result.help).toBe(true);\n    });\n\n    test(\"parses --help flag for help\", () => {\n      const result = parseArgs([\"--help\"]);\n      expect(result.help).toBe(true);\n    });\n\n    test(\"handles no arguments\", () => {\n      const result = parseArgs([]);\n      expect(result.files).toEqual([]);\n      expect(result.quiet).toBe(false);\n      expect(result.help).toBe(false);\n    });\n\n    test(\"handles mixed flags and files\", () => {\n      const result = parseArgs([\"-q\", \"file1.yaml\", \"--help\", \"file2.yaml\"]);\n      expect(result.quiet).toBe(true);\n      expect(result.help).toBe(true);\n      expect(result.files).toEqual([\"file1.yaml\", \"file2.yaml\"]);\n    });\n\n    test(\"ignores unknown flags starting with dash\", () => {\n      const result = parseArgs([\"--unknown\", \"-x\", \"file.yaml\"]);\n      expect(result.files).toEqual([\"file.yaml\"]);\n    });\n\n    test(\"handles glob pattern as file argument\", () => {\n      const result = parseArgs([\"*.yaml\", \"config/**/*.yml\"]);\n      expect(result.files).toEqual([\"*.yaml\", \"config/**/*.yml\"]);\n    });\n  });\n\n  describe(\"formatError\", () => {\n    test(\"formats error in file:line:col: message format\", () => {\n      const error = { line: 15, column: 3, message: \"Test error message\" };\n      const result = formatError(\"config/app.yaml\", error);\n      expect(result).toBe(\"config/app.yaml:15:3: Test error message\");\n    });\n\n    test(\"handles single digit line and column\", () => {\n      const error = { line: 1, column: 1, message: \"Error\" };\n      const result = formatError(\"file.yaml\", error);\n      expect(result).toBe(\"file.yaml:1:1: Error\");\n    });\n  });\n\n  describe(\"formatFileError\", () => {\n    test(\"formats file error in file: message format\", () => {\n      const result = formatFileError(\"config/db.yaml\", \"File not found\");\n      expect(result).toBe(\"config/db.yaml: File not found\");\n    });\n  });\n\n  describe(\"readYamlFile\", () => {\n    test(\"reads existing file successfully\", async () => {\n      const result = await readYamlFile(join(TEST_FIXTURES_DIR, \"valid.yaml\"));\n      expect(result.content).toBeDefined();\n      expect(result.error).toBeUndefined();\n      expect(result.content).toContain(\"name: test\");\n    });\n\n    test(\"returns error for missing file\", async () => {\n      const result = await readYamlFile(join(TEST_FIXTURES_DIR, \"nonexistent.yaml\"));\n      expect(result.error).toBeDefined();\n      expect(result.error).toContain(\"File not found\");\n      expect(result.content).toBeUndefined();\n    });\n\n    test(\"rejects URL paths (http://)\", async () => {\n      const result = await readYamlFile(\"http://example.com/file.yaml\");\n      expect(result.error).toBe(\"Only local file paths are allowed\");\n    });\n\n    test(\"rejects URL paths (https://)\", async () => {\n      const result = await readYamlFile(\"https://example.com/file.yaml\");\n      expect(result.error).toBe(\"Only local file paths are allowed\");\n    });\n\n    test(\"rejects URL paths (ftp://)\", async () => {\n      const result = await readYamlFile(\"ftp://example.com/file.yaml\");\n      expect(result.error).toBe(\"Only local file paths are allowed\");\n    });\n\n    test(\"rejects path traversal outside working directory\", async () => {\n      const result = await readYamlFile(\"../../../etc/passwd\");\n      expect(result.error).toBe(\"Path traversal outside working directory is not allowed\");\n    });\n  });\n\n  describe(\"resolveGlob\", () => {\n    test(\"resolves *.yaml pattern\", async () => {\n      const matches = await resolveGlob(join(TEST_FIXTURES_DIR, \"*.yaml\"));\n      expect(matches.length).toBeGreaterThan(0);\n      expect(matches.every((f) => f.endsWith(\".yaml\"))).toBe(true);\n    });\n\n    test(\"resolves *.yml pattern\", async () => {\n      const matches = await resolveGlob(join(TEST_FIXTURES_DIR, \"*.yml\"));\n      expect(matches.length).toBeGreaterThan(0);\n      expect(matches.every((f) => f.endsWith(\".yml\"))).toBe(true);\n    });\n\n    test(\"resolves recursive **/*.yaml pattern\", async () => {\n      const matches = await resolveGlob(join(TEST_FIXTURES_DIR, \"**/*.yaml\"));\n      expect(matches.length).toBeGreaterThan(0);\n      const hasNestedFile = matches.some((f) => f.includes(\"subdir\"));\n      expect(hasNestedFile).toBe(true);\n    });\n\n    test(\"filters to only .yaml and .yml files\", async () => {\n      const matches = await resolveGlob(join(TEST_FIXTURES_DIR, \"*\"));\n      expect(matches.every((f) => f.endsWith(\".yaml\") || f.endsWith(\".yml\"))).toBe(true);\n      expect(matches.some((f) => f.endsWith(\".txt\"))).toBe(false);\n    });\n\n    test(\"returns empty array for non-matching pattern\", async () => {\n      const matches = await resolveGlob(join(TEST_FIXTURES_DIR, \"*.nonexistent\"));\n      expect(matches).toEqual([]);\n    });\n  });\n\n  describe(\"resolveFiles\", () => {\n    test(\"passes through direct file paths\", async () => {\n      const files = await resolveFiles([\"file1.yaml\", \"file2.yaml\"]);\n      expect(files).toEqual([\"file1.yaml\", \"file2.yaml\"]);\n    });\n\n    test(\"expands glob patterns\", async () => {\n      const files = await resolveFiles([join(TEST_FIXTURES_DIR, \"*.yaml\")]);\n      expect(files.length).toBeGreaterThan(0);\n      expect(files.every((f) => f.endsWith(\".yaml\"))).toBe(true);\n    });\n\n    test(\"handles mix of direct paths and globs\", async () => {\n      const files = await resolveFiles([\"direct.yaml\", join(TEST_FIXTURES_DIR, \"*.yaml\")]);\n      expect(files[0]).toBe(\"direct.yaml\");\n      expect(files.length).toBeGreaterThan(1);\n    });\n  });\n\n  describe(\"validateFiles\", () => {\n    test(\"validates valid file successfully\", async () => {\n      const results = await validateFiles([join(TEST_FIXTURES_DIR, \"valid.yaml\")]);\n      expect(results).toHaveLength(1);\n      expect(results[0].valid).toBe(true);\n      expect(results[0].errors).toHaveLength(0);\n      expect(results[0].fileError).toBeUndefined();\n    });\n\n    test(\"reports errors for invalid file\", async () => {\n      const results = await validateFiles([join(TEST_FIXTURES_DIR, \"invalid-string.yaml\")]);\n      expect(results).toHaveLength(1);\n      expect(results[0].valid).toBe(false);\n      expect(results[0].errors.length).toBeGreaterThan(0);\n    });\n\n    test(\"reports file error for missing file\", async () => {\n      const results = await validateFiles([join(TEST_FIXTURES_DIR, \"nonexistent.yaml\")]);\n      expect(results).toHaveLength(1);\n      expect(results[0].valid).toBe(false);\n      expect(results[0].fileError).toBeDefined();\n      expect(results[0].fileError).toContain(\"File not found\");\n    });\n\n    test(\"validates multiple files independently (REQ-002)\", async () => {\n      const results = await validateFiles([\n        join(TEST_FIXTURES_DIR, \"valid.yaml\"),\n        join(TEST_FIXTURES_DIR, \"invalid-string.yaml\"),\n        join(TEST_FIXTURES_DIR, \"valid-list.yml\"),\n      ]);\n      expect(results).toHaveLength(3);\n      expect(results[0].valid).toBe(true);\n      expect(results[1].valid).toBe(false);\n      expect(results[2].valid).toBe(true);\n    });\n\n    test(\"continues validation even if some files fail (REQ-002)\", async () => {\n      const results = await validateFiles([\n        join(TEST_FIXTURES_DIR, \"nonexistent.yaml\"),\n        join(TEST_FIXTURES_DIR, \"valid.yaml\"),\n      ]);\n      expect(results).toHaveLength(2);\n      expect(results[0].fileError).toBeDefined();\n      expect(results[1].valid).toBe(true);\n    });\n  });\n});\n\n// ============================================================================\n// Integration Tests: CLI Behavior\n// ============================================================================\n\ndescribe(\"CLI Integration\", () => {\n  test(\"exits 0 for valid file\", async () => {\n    const proc = Bun.spawn([\"bun\", \"run\", \"src/yaml-validator.ts\", join(TEST_FIXTURES_DIR, \"valid.yaml\")], {\n      cwd: process.cwd(),\n      stdout: \"pipe\",\n      stderr: \"pipe\",\n    });\n    const exitCode = await proc.exited;\n    expect(exitCode).toBe(0);\n  });\n\n  test(\"exits 1 for invalid YAML\", async () => {\n    const proc = Bun.spawn([\"bun\", \"run\", \"src/yaml-validator.ts\", join(TEST_FIXTURES_DIR, \"invalid-string.yaml\")], {\n      cwd: process.cwd(),\n      stdout: \"pipe\",\n      stderr: \"pipe\",\n    });\n    const exitCode = await proc.exited;\n    expect(exitCode).toBe(1);\n  });\n\n  test(\"exits 2 for missing file\", async () => {\n    const proc = Bun.spawn([\"bun\", \"run\", \"src/yaml-validator.ts\", join(TEST_FIXTURES_DIR, \"nonexistent.yaml\")], {\n      cwd: process.cwd(),\n      stdout: \"pipe\",\n      stderr: \"pipe\",\n    });\n    const exitCode = await proc.exited;\n    expect(exitCode).toBe(2);\n  });\n\n  test(\"exits 2 for no files specified\", async () => {\n    const proc = Bun.spawn([\"bun\", \"run\", \"src/yaml-validator.ts\"], {\n      cwd: process.cwd(),\n      stdout: \"pipe\",\n      stderr: \"pipe\",\n    });\n    const exitCode = await proc.exited;\n    expect(exitCode).toBe(2);\n  });\n\n  test(\"--help exits 0 and shows usage\", async () => {\n    const proc = Bun.spawn([\"bun\", \"run\", \"src/yaml-validator.ts\", \"--help\"], {\n      cwd: process.cwd(),\n      stdout: \"pipe\",\n      stderr: \"pipe\",\n    });\n    const exitCode = await proc.exited;\n    const stdout = await new Response(proc.stdout).text();\n    expect(exitCode).toBe(0);\n    expect(stdout).toContain(\"Usage:\");\n    expect(stdout).toContain(\"--quiet\");\n    expect(stdout).toContain(\"--help\");\n  });\n\n  test(\"--quiet suppresses success messages\", async () => {\n    const proc = Bun.spawn([\"bun\", \"run\", \"src/yaml-validator.ts\", \"--quiet\", join(TEST_FIXTURES_DIR, \"valid.yaml\")], {\n      cwd: process.cwd(),\n      stdout: \"pipe\",\n      stderr: \"pipe\",\n    });\n    const exitCode = await proc.exited;\n    const stdout = await new Response(proc.stdout).text();\n    expect(exitCode).toBe(0);\n    expect(stdout.trim()).toBe(\"\");\n  });\n\n  test(\"--quiet still shows errors\", async () => {\n    const proc = Bun.spawn(\n      [\"bun\", \"run\", \"src/yaml-validator.ts\", \"--quiet\", join(TEST_FIXTURES_DIR, \"invalid-string.yaml\")],\n      {\n        cwd: process.cwd(),\n        stdout: \"pipe\",\n        stderr: \"pipe\",\n      }\n    );\n    const exitCode = await proc.exited;\n    const stderr = await new Response(proc.stderr).text();\n    expect(exitCode).toBe(1);\n    expect(stderr).toContain(\"Unterminated\");\n  });\n\n  test(\"outputs errors to stderr with file:line:col format (REQ-003)\", async () => {\n    const proc = Bun.spawn([\"bun\", \"run\", \"src/yaml-validator.ts\", join(TEST_FIXTURES_DIR, \"invalid-string.yaml\")], {\n      cwd: process.cwd(),\n      stdout: \"pipe\",\n      stderr: \"pipe\",\n    });\n    await proc.exited;\n    const stderr = await new Response(proc.stderr).text();\n    expect(stderr).toMatch(/.*:\\d+:\\d+:/);\n  });\n\n  test(\"validates multiple files and reports all results\", async () => {\n    const proc = Bun.spawn(\n      [\n        \"bun\",\n        \"run\",\n        \"src/yaml-validator.ts\",\n        join(TEST_FIXTURES_DIR, \"valid.yaml\"),\n        join(TEST_FIXTURES_DIR, \"invalid-string.yaml\"),\n      ],\n      {\n        cwd: process.cwd(),\n        stdout: \"pipe\",\n        stderr: \"pipe\",\n      }\n    );\n    const exitCode = await proc.exited;\n    const stdout = await new Response(proc.stdout).text();\n    const stderr = await new Response(proc.stderr).text();\n    expect(exitCode).toBe(1);\n    expect(stdout).toC