        "content": "/**\n * Lightweight Inline YAML Syntax Validator\n * Tests whether common YAML errors can be detected without external libraries\n * DISPOSABLE - Experimental code for hypothesis validation\n */\n\ninterface ValidationError {\n  line: number;\n  column: number;\n  message: string;\n  type: 'indentation' | 'string' | 'key' | 'structure' | 'document';\n}\n\ninterface ValidationResult {\n  valid: boolean;\n  errors: ValidationError[];\n}\n\nfunction validateYAML(content: string): ValidationResult {\n  const errors: ValidationError[] = [];\n  const lines = content.split('\\n');\n\n  let inMultilineString = false;\n  let multilineStringIndent = 0;\n  let multilineStringType: '|' | '>' | null = null;\n  let expectedIndent = 0;\n  let indentStack: number[] = [0];\n  let inFlowContext = 0; // Track { } and [ ] nesting\n\n  for (let i = 0; i < lines.length; i++) {\n    const line = lines[i];\n    const lineNum = i + 1;\n    const trimmed = line.trimStart();\n    const leadingSpaces = line.length - trimmed.length;\n\n    // Skip empty lines and comments\n    if (trimmed === '' || trimmed.startsWith('#')) {\n      continue;\n    }\n\n    // Check for document markers\n    if (trimmed === '---' || trimmed === '...') {\n      // Reset state for new document\n      indentStack = [0];\n      inMultilineString = false;\n      continue;\n    }\n\n    // Check for tabs (YAML should use spaces)\n    if (line.includes('\\t')) {\n      errors.push({\n        line: lineNum,\n        column: line.indexOf('\\t') + 1,\n        message: 'Tabs are not allowed in YAML, use spaces for indentation',\n        type: 'indentation'\n      });\n    }\n\n    // Handle multiline strings (literal | and folded >)\n    if (inMultilineString) {\n      if (leadingSpaces <= multilineStringIndent && trimmed !== '') {\n        inMultilineString = false;\n        multilineStringType = null;\n      } else {\n        continue;\n      }\n    }\n\n    // Track flow context (braces and brackets)\n    for (const char of line) {\n      if (char === '{' || char === '[') inFlowContext++;\n      if (char === '}' || char === ']') inFlowContext--;\n    }\n\n    // Skip indentation checks inside flow context\n    if (inFlowContext > 0) {\n      continue;\n    }\n\n    // Check indentation consistency (must be consistent increments)\n    if (leadingSpaces > 0) {\n      const lastIndent = indentStack[indentStack.length - 1];\n\n      if (leadingSpaces > lastIndent) {\n        // New indent level\n        indentStack.push(leadingSpaces);\n      } else if (leadingSpaces < lastIndent) {\n        // Dedent - must match a previous level\n        while (indentStack.length > 1 && indentStack[indentStack.length - 1] > leadingSpaces) {\n          indentStack.pop();\n        }\n        if (indentStack[indentStack.length - 1] !== leadingSpaces) {\n          errors.push({\n            line: lineNum,\n            column: leadingSpaces + 1,\n            message: `Invalid indentation: ${leadingSpaces} spaces does not match any previous indentation level`,\n            type: 'indentation'\n          });\n        }\n      }\n    } else {\n      // Reset to root level\n      indentStack = [0];\n    }\n\n    // Check for unterminated strings\n    const singleQuoteCount = (trimmed.match(/'/g) || []).length;\n    const doubleQuoteCount = (trimmed.match(/\"/g) || []).length;\n    const escapedSingleQuotes = (trimmed.match(/''/g) || []).length * 2;\n    const escapedDoubleQuotes = (trimmed.match(/\\\\\"/g) || []).length;\n\n    // Adjust for escaped quotes\n    const effectiveSingleQuotes = singleQuoteCount - escapedSingleQuotes;\n    const effectiveDoubleQuotes = doubleQuoteCount - escapedDoubleQuotes;\n\n    if (effectiveSingleQuotes % 2 !== 0) {\n      errors.push({\n        line: lineNum,\n        column: line.indexOf(\"'\") + 1,\n        message: 'Unterminated single-quoted string',\n        type: 'string'\n      });\n    }\n\n    if (effectiveDoubleQuotes % 2 !== 0) {\n      errors.p