esult = await readYamlFile(\"http://example.com/file.yaml\");\nconsole.log(\"URL rejection:\", urlResult.error);\nconsole.assert(urlResult.error === \"Only local file paths are allowed\", \"Should reject URLs\");\n\nconst ftpResult = await readYamlFile(\"ftp://example.com/file.yaml\");\nconsole.assert(ftpResult.error === \"Only local file paths are allowed\", \"Should reject FTP URLs\");\n\n// Test non-existent file\nconst missingResult = await readYamlFile(\"nonexistent.yaml\");\nconsole.log(\"Missing file:\", missingResult.error);\nconsole.assert(missingResult.error?.includes(\"File not found\"), \"Should report file not found\");\n\n// Test reading existing file\nconst existingResult = await readYamlFile(\"./src/yaml-parser.ts\");\nconsole.log(\"Existing file:\", existingResult.content ? \"Read successfully (\" + existingResult.content.length + \" bytes)\" : existingResult.error);\nconsole.assert(existingResult.content && existingResult.content.length > 0, \"Should read existing file\");\n\nconsole.log(\"T3: All tests passed!\");\n\n// Test T4: formatError and formatFileError\nconsole.log(\"\\n=== T4: formatError tests ===\");\n\nconst errorMsg = formatError(\"config/app.yaml\", { line: 15, column: 3, message: \"Invalid indentation\" });\nconsole.log(\"formatError:\", errorMsg);\nconsole.assert(errorMsg === \"config/app.yaml:15:3: Invalid indentation\", \"Should format error correctly\");\n\nconst fileErrorMsg = formatFileError(\"config/db.yaml\", \"File not found\");\nconsole.log(\"formatFileError:\", fileErrorMsg);\nconsole.assert(fileErrorMsg === \"config/db.yaml: File not found\", \"Should format file error correctly\");\n\nconsole.log(\"T4: All tests passed!\");\n\nconsole.log(\"\\n=== All T2, T3, T4 tests passed! ===\");\n'",
