        "old_string": "/**\n * Resolve a glob pattern to a list of matching YAML files.\n *\n * @param pattern - Glob pattern to match (e.g., \"config/*.yaml\", \"**\\/*.yml\")\n * @returns Array of matching file paths (only .yaml and .yml files)\n *\n * Features:\n * - Uses Bun.Glob for native glob pattern matching\n * - Filters results to only .yaml and .yml extensions (BR-001)\n * - Excludes dot files by default\n * - Supports recursive patterns (e.g., \"**\\/*.yaml\")\n * - Returns empty array if no files match (graceful handling)\n */\nexport async function resolveGlob(pattern: string): Promise<string[]> {\n  const glob = new Bun.Glob(pattern);\n  const matches: string[] = [];\n\n  for await (const path of glob.scan({ dot: false })) {\n    if (path.endsWith(\".yaml\") || path.endsWith(\".yml\")) {\n      matches.push(path);\n    }\n  }\n\n  return matches;\n}",
        "new_string": "/**\n * Resolve a glob pattern to a list of matching YAML files.\n *\n * @param pattern - Glob pattern to match (e.g., \"config/*.yaml\", \"**\\/*.yml\")\n * @returns Array of matching file paths (only .yaml and .yml files)\n *\n * Features:\n * - Uses Bun.Glob for native glob pattern matching\n * - Filters results to only .yaml and .yml extensions (BR-001)\n * - Excludes dot files by default\n * - Supports recursive patterns (e.g., \"**\\/*.yaml\")\n * - Returns empty array if no files match (graceful handling)\n */\nexport async function resolveGlob(pattern: string): Promise<string[]> {\n  const glob = new Bun.Glob(pattern);\n  const matches: string[] = [];\n\n  for await (const path of glob.scan({ dot: false })) {\n    if (path.endsWith(\".yaml\") || path.endsWith(\".yml\")) {\n      matches.push(path);\n    }\n  }\n\n  return matches;\n}\n\n// ============================================================================\n// Validator Orchestrator\n// ============================================================================\n\nconst HELP_TEXT = `Usage: bun run validate-yaml [options] <file...>\n\nValidate YAML file syntax.\n\nArguments:\n  file...              YAML file paths or glob patterns\n\nOptions:\n  -q, --quiet          Only output errors, suppress success messages\n  -h, --help           Show this help message\n\nExit Codes:\n  0                    All files valid\n  1                    One or more files have validation errors\n  2                    Invalid arguments or file access errors\n\nExamples:\n  bun run validate-yaml config.yaml\n  bun run validate-yaml config.yaml settings.yaml\n  bun run validate-yaml \"config/**/*.yaml\"\n  bun run validate-yaml --quiet config.yaml\n`;\n\nconst USAGE_TEXT = `Usage: bun run validate-yaml [options] <file...>\nTry 'bun run validate-yaml --help' for more information.\n`;\n\n/**\n * Print help text to stdout.\n */\nexport function printHelp(): void {\n  console.log(HELP_TEXT);\n}\n\n/**\n * Print short usage text to stderr for error cases.\n */\nexport function printUsage(): void {\n  console.error(USAGE_TEXT);\n}\n\n/**\n * Check if a pattern looks like a glob pattern.\n */\nfunction isGlobPattern(pattern: string): boolean {\n  return pattern.includes(\"*\") || pattern.includes(\"?\") || pattern.includes(\"[\");\n}\n\n/**\n * Resolve file arguments to a list of file paths, expanding glob patterns.\n *\n * @param fileArgs - Array of file paths or glob patterns\n * @returns Array of resolved file paths\n */\nexport async function resolveFiles(fileArgs: string[]): Promise<string[]> {\n  const resolvedFiles: string[] = [];\n\n  for (const arg of fileArgs) {\n    if (isGlobPattern(arg)) {\n      const matches = await resolveGlob(arg);\n      resolvedFiles.push(...matches);\n    } else {\n      resolvedFiles.push(arg);\n    }\n  }\n\n  return resolvedFiles;\n}\n\n/**\n * Validate multiple files and collect results.\n *\n * @param files - Array of file paths to validate\n * @returns Array of FileValidationResult for each file\n */\nexport async function validateFiles(files: string[]): Promise<FileValidationResult[]> {\n  const results: FileValidationResult[] = [];\n\n  for (const filePath of files) {\n    const readResult = await readYamlFile(filePath);\n\n    if (readResult.error) {\n      results.push({\n        path: filePath,\n        valid: false,\n        errors: [],\n        fileError: readResult.error,\n      });\n      continue;\n    }\n\n    const validationResult = validateMultiDocYaml(readResult.content!);\n    results.push({\n      path: filePath,\n      valid: validationResult.valid,\n      errors: validationResult.errors,\n    });\n  }\n\n  return results;\n}\n\n/**\n * Output validation results to stdout/stderr based on quiet mode.\n *\n * @param results - Array of FileValidationResult\n * @param quiet - If true, suppress success messages\n */\nexport function outputResults(results: FileValidationResult[], quiet: boolean): void {\n  for (const result of results) {\n    if (result.fileError) {\n      console.error(formatFileError(result.path, result.fileError));\n    } else if (!result.valid) {\n      for (const error of result.errors) {\n        console.error(formatError(result.path, error));\n      }\n    } else if (!quiet) {\n      console.log(`${result.path}: OK`);\n    }\n  }\n}\n\n/**\n * Main CLI entry point for the YAML validator.\n * Integrates argument parsing, file reading, glob handling, validation, and output.\n */\nexport async function main(): Promise<void> {\n  const args = process.argv.slice(2);\n  const options = parseArgs(args);\n\n  if (options.help) {\n    printHelp();\n    process.exit(0);\n  }\n\n  if (options.files.length === 0) {\n    console.error(\"Error: No files specified\");\n    printUsage();\n    process.exit(2);\n  }\n\n  const resolvedFiles = await resolveFiles(options.files);\n\n  if (resolvedFiles.length === 0) {\n    console.error(\"Error: No files matched the specified patterns\");\n    process.exit(2);\n  }\n\n  const results = await validateFiles(resolvedFiles);\n\n  outputResults(results, options.quiet);\n\n  const hasFileErrors = results.some((r) => r.fileError !== undefined);\n  const hasValidationErrors = results.some((r) => !r.valid && !r.fileError);\n\n  if (hasFileErrors) {\n    process.exit(2);\n  } else if (hasValidationErrors) {\n    process.exit(1);\n  } else {\n    process.exit(0);\n  }\n}\n\nmain();"
