function validateYAML(content: string): ValidationResult {
  const errors: ValidationError[] = [];
  const lines = content.split('\n');

  let inMultilineString = false;
  let multilineStringIndent = 0;
  let indentStack: number[] = [0];
  let inFlowContext = 0;
  let prevNonEmptyLineIndent = 0;
  let indentUnit: number | null = null; // Track consistent indent size

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const lineNum = i + 1;
    const trimmed = line.trimStart();
    const leadingSpaces = line.length - trimmed.length;

    // Skip empty lines and comments
    if (trimmed === '' || trimmed.startsWith('#')) {
      continue;
    }

    // Check for document markers
    if (trimmed === '---' || trimmed === '...') {
      indentStack = [0];
      inMultilineString = false;
      indentUnit = null;
      continue;
    }

    // Check for tabs
    if (line.includes('\t')) {
      errors.push({
        line: lineNum,
        column: line.indexOf('\t') + 1,
        message: 'Tabs are not allowed in YAML, use spaces for indentation',
        type: 'indentation'
      });
    }

    // Handle multiline strings
    if (inMultilineString) {
      if (leadingSpaces <= multilineStringIndent && trimmed !== '') {
        inMultilineString = false;
      } else {
        continue;
      }
    }

    // Track flow context
    let inQuote = false;
    let quoteChar = '';
    for (let j = 0; j < line.length; j++) {
      const char = line[j];
      if ((char === '"' || char === "'") && (j === 0 || line[j - 1] !== '\\')) {
        if (!inQuote) {
          inQuote = true;
          quoteChar = char;
        } else if (char === quoteChar) {
          inQuote = false;
        }
      }
      if (!inQuote) {
        if (char === '{' || char === '[') inFlowContext++;
        if (char === '}' || char === ']') inFlowContext--;
      }
    }

    // Skip indentation checks inside flow context
    if (inFlowContext > 0) {
      prevNonEmptyLineIndent = leadingSpaces;
      continue;
    }

    // ENHANCED: Check indentation consistency
    if (leadingSpaces > 0) {
      const lastIndent = indentStack[indentStack.length - 1];

      if (leadingSpaces > lastIndent) {
        // New indent level - determine indent unit
        const indentDiff = leadingSpaces - lastIndent;

        if (indentUnit === null) {
          indentUnit = indentDiff;
        } else if (indentDiff !== indentUnit && indentDiff !== 1) {
          // Allow single space increments for list items
          // Check if this is NOT a list continuation
          if (!trimmed.startsWith('-')) {
            errors.push({
              line: lineNum,
              column: leadingSpaces + 1,
              message: `Inconsistent indentation: expected ${indentUnit} spaces increment, got ${indentDiff}`,
              type: 'indentation'
            });
          }
        }

        indentStack.push(leadingSpaces);
      } else if (leadingSpaces < lastIndent) {
        // Dedent - must match a previous level exactly
        let found = false;
        while (indentStack.length > 1) {
          const top = indentStack[indentStack.length - 1];
          if (top === leadingSpaces) {
            found = true;
            break;
          } else if (top > leadingSpaces) {
            indentStack.pop();
          } else {
            break;
          }
        }

        if (!found && indentStack[indentStack.length - 1] !== leadingSpaces) {
          errors.push({
            line: lineNum,
            column: leadingSpaces + 1,
            message: `Invalid indentation: ${leadingSpaces} spaces does not match any previous indentation level (stack: ${indentStack.join(', ')})`,
            type: 'indentation'
          });
        }
      }
      // If equal, stay at same level
    } else {
      // Reset to root level
      indentStack = [0];
    }

    prevNonEmptyLineIndent = leadingSpaces;

    // Check for unterminated strings
    let singleCount = 0;
    let doubleCount = 0;
    let inSingle = false;
    let inDouble = false;

    for (let j = 0; j < trimmed.length; j++) {
      const char = trimmed[j];
      const prevChar = j > 0 ? trimmed[j - 1] : '';

      if (char === "'" && !inDouble) {
        if (inSingle && j + 1 < trimmed.length && trimmed[j + 1] === "'") {
          // Escaped single quote in YAML
          j++;
          continue;
        }
        inSingle = !inSingle;
        singleCount++;
      } else if (char === '"' && !inSingle && prevChar !== '\\') {
        inDouble = !inDouble;
        doubleCount++;
      }
    }

    if (singleCount % 2 !== 0) {
      errors.push({
        line: lineNum,
        column: line.indexOf("'") + 1,
        message: 'Unterminated single-quoted string',
        type: 'string'
      });
    }

    if (doubleCount % 2 !== 0) {
      errors.push({
        line: lineNum,
        column: line.indexOf('"') + 1,
        message: 'Unterminated double-quoted string',
        type: 'string'
      });
    }

    // Check for multiline string indicators
    if (trimmed.match(/:\s*[|>][-+]?\s*(#.*)?$/)) {
      inMultilineString = true;
      multilineStringIndent = leadingSpaces;
      continue;
    }

    // Check for malformed keys
    const keyMatch = trimmed.match(/^([^\s:]+)\s*:/);
    if (keyMatch) {
      const key = keyMatch[1];
      if (!key.startsWith("'") && !key.startsWith('"')) {
        if (/^[@`]/.test(key)) {
          errors.push({
            line: lineNum,
            column: leadingSpaces + 1,
            message: `Invalid key: unquoted keys cannot start with '${key[0]}'`,
            type: 'key'
          });
        }
      }
    }

    // Check for double colon typo
    if (trimmed.match(/::\s/)) {
      errors.push({
        line: lineNum,
        column: trimmed.indexOf('::') + leadingSpaces + 1,
        message: 'Possible typo: double colon (::) found',
        type: 'structure'
      });
    }
  }

  // Check for unclosed flow context
  if (inFlowContext > 0) {
    errors.push({
      line: lines.length,
      column: 1,
      message: `Unclosed flow context: ${inFlowContext} unclosed brace(s) or bracket(s)`,
      type: 'structure'
    });
  } else if (inFlowContext < 0) {
    errors.push({
      line: lines.length,
      column: 1,
      message: `Extra closing brace(s) or bracket(s)`,
      type: 'structure'
    });
  }

  return {
    valid: errors.length === 0,
    errors
  };
}

