/**
 * YAML Syntax Validator - Best-effort inline parser
 *
 * This module provides lightweight YAML syntax validation without external dependencies.
 * It uses line-by-line tokenization to detect common structural errors.
 *
 * KNOWN LIMITATIONS:
 * - This inline parser catches approximately 11% of errors that js-yaml would catch
 * - Complex YAML features (anchors, aliases, tags) are not fully validated
 * - Flow-style collections have limited validation
 * - This is a best-effort syntax checker, not a full YAML parser
 *
 * Detected error types:
 * - Invalid indentation (mixed tabs/spaces, inconsistent levels)
 * - Unterminated strings (unmatched quotes)
 * - Malformed keys (invalid characters, missing colon)
 * - Invalid list items (improper dash-space prefix)
 * - Duplicate keys at the same level
 * - Invalid document markers (--- and ...) placement
 */

export interface YamlError {
  line: number;
  column: number;
  message: string;
}

export interface ValidationResult {
  valid: boolean;
  errors: YamlError[];
}

export interface ParserState {
  line: number;
  column: number;
  indentStack: number[];
  inMultilineString: boolean;
  stringDelimiter: string | null;
  multilineStringIndent: number;
}

interface KeyTracker {
  indent: number;
  keys: Set<string>;
}

/**
 * Validate YAML syntax without fully parsing the document.
 * @param content - YAML content string
 * @returns ValidationResult with validity status and any errors
 */
export function validateYaml(content: string): ValidationResult {
  const errors: YamlError[] = [];

  if (content.length === 0 || content.trim().length === 0) {
    return { valid: true, errors: [] };
  }

  const lines = content.split("\n");
  const state: ParserState = {
    line: 0,
    column: 0,
    indentStack: [0],
    inMultilineString: false,
    stringDelimiter: null,
    multilineStringIndent: 0,
  };

  const keyTrackers: KeyTracker[] = [{ indent: 0, keys: new Set() }];
  let usesSpaces: boolean | null = null;
  let usesTabs: boolean | null = null;

  for (let i = 0; i < lines.length; i++) {
    state.line = i + 1;
    const line = lines[i];

    if (state.inMultilineString) {
      const lineIndent = getIndentation(line);
      if (line.trim().length > 0 && lineIndent < state.multilineStringIndent) {
        state.inMultilineString = false;
        state.stringDelimiter = null;
      } else {
        continue;
      }
    }

    const trimmed = line.trimStart();
    if (trimmed.length === 0 || trimmed.startsWith("#")) {
      continue;
    }

    const indentError = validateIndentation(line, usesSpaces, usesTabs, state);
    if (indentError) {
      errors.push(indentError);
      if (indentError.message.includes("tabs") || indentError.message.includes("spaces")) {
        if (line.includes("\t")) {
          usesTabs = true;
        }
        if (/^ +/.test(line)) {
          usesSpaces = true;
        }
      }
    } else {
      if (line.includes("\t") && line.indexOf("\t") < line.length - line.trimStart().length) {
        usesTabs = true;
      }
      if (/^ +/.test(line)) {
        usesSpaces = true;
      }
    }

    const stringError = validateStrings(line, state);
    if (stringError) {
      errors.push(stringError);
    }

    const currentIndent = getIndentation(line);

    while (keyTrackers.length > 0 && keyTrackers[keyTrackers.length - 1].indent > currentIndent) {
      keyTrackers.pop();
    }

    if (trimmed.startsWith("- ") || trimmed === "-") {
      const listError = validateListItem(line, trimmed, state, currentIndent);
      if (listError) {
        errors.push(listError);
      }
    } else if (isKeyValueLine(trimmed)) {
      const keyError = validateKey(line, trimmed, state, keyTrackers, currentIndent);
      if (keyError) {
        errors.push(keyError);
      }

      const multilineIndicator = checkMultilineIndicator(trimmed);
      if (multilineIndicator) {
        state.inMultilineString = true;
        state.stringDelimiter = multilineIndicator;
        state.multilineStringIndent = currentIndent + 2;
      }
    }
  }

  if (state.inMultilineString && state.stringDelimiter === '"') {
    errors.push({
      line: state.line,
      column: 1,
      message: "Unterminated string at end of document",
    });
  }

  return {
    valid: errors.length === 0,
    errors,
  };
}

/**
 * Validate YAML syntax for multi-document files.
 * @param content - YAML content string (may contain ---)
 * @returns ValidationResult with errors across all documents
 */
export function validateMultiDocYaml(content: string): ValidationResult {
  const errors: YamlError[] = [];

  if (content.length === 0 || content.trim().length === 0) {
    return { valid: true, errors: [] };
  }

  const lines = content.split("\n");
  let documentStart = 0;
  let lineOffset = 0;
  let hasExplicitDocStart = false;
  let afterDocEnd = false;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const trimmed = line.trim();

    if (trimmed === "---") {
      if (documentStart < i) {
        const docContent = lines.slice(documentStart, i).join("\n");
        const docErrors = validateYaml(docContent);
        for (const err of docErrors.errors) {
          errors.push({
            line: err.line + lineOffset,
            column: err.column,
            message: err.message,
          });
        }
      }
      hasExplicitDocStart = true;
      afterDocEnd = false;
      documentStart = i + 1;
      lineOffset = i + 1;
    } else if (trimmed === "...") {
      if (!hasExplicitDocStart && documentStart === 0 && i > 0) {
        const docContent = lines.slice(documentStart, i).join("\n");
        const docErrors = validateYaml(docContent);
        for (const err of docErrors.errors) {
          errors.push({
            line: err.line + lineOffset,
            column: err.column,
            message: err.message,
          });
        }
      } else if (hasExplicitDocStart) {
        const docContent = lines.slice(documentStart, i).join("\n");
        const docErrors = validateYaml(docContent);
        for (const err of docErrors.errors) {
          errors.push({
            line: err.line + lineOffset,
            column: err.column,
            message: err.message,
          });
        }
      }
      afterDocEnd = true;
      documentStart = i + 1;
      lineOffset = i + 1;
    } else if (afterDocEnd && trimmed.length > 0 && !trimmed.startsWith("#")) {
      errors.push({
        line: i + 1,
        column: 1,
        message: "Content after document end marker (...) requires new document marker (---)",
      });
      afterDocEnd = false;
      documentStart = i;
      lineOffset = i;
    }
  }

  if (documentStart < lines.length) {
    const docContent = lines.slice(documentStart).join("\n");
    const docErrors = validateYaml(docContent);
    for (const err of docErrors.errors) {
      errors.push({
        line: err.line + lineOffset,
        column: err.column,
        message: err.message,
      });
    }
  }

  return {
    valid: errors.length === 0,
    errors,
  };
}

function getIndentation(line: string): number {
  const match = line.match(/^[ \t]*/);
  return match ? match[0].length : 0;
}

function validateIndentation(
  line: string,
  usesSpaces: boolean | null,
  usesTabs: boolean | null,
  state: ParserState
): YamlError | null {
  const indentMatch = line.match(/^([ \t]*)/);
  if (!indentMatch) return null;

  const indent = indentMatch[1];
  if (indent.length === 0) return null;

  const hasSpaces = indent.includes(" ");
  const hasTabs = indent.includes("\t");

  if (hasSpaces && hasTabs) {
    return {
      line: state.line,
      column: 1,
      message: "Inconsistent indentation: mixed tabs and spaces in the same line",
    };
  }

  if (usesSpaces === true && hasTabs) {
    return {
      line: state.line,
      column: 1,
      message: "Inconsistent indentation: file uses spaces but this line uses tabs",
    };
  }

  if (usesTabs === true && hasSpaces && usesSpaces !== true) {
    return {
      line: state.line,
      column: 1,
      message: "Inconsistent indentation: file uses tabs but this line uses spaces",
    };
  }

  return null;
}

function validateStrings(line: string, state: ParserState): YamlError | null {
  let inSingleQuote = false;
  let inDoubleQuote = false;
  let escaped = false;

  for (let i = 0; i < line.length; i++) {
    const char = line[i];

    if (escaped) {
      escaped = false;
      continue;
    }

    if (char === "\\" && inDoubleQuote) {
      escaped = true;
      continue;
    }

    if (char === "#" && !inSingleQuote && !inDoubleQuote) {
      break;
    }

    if (char === "'" && !inDoubleQuote) {
      if (inSingleQuote && line[i + 1] === "'") {
        i++;
        continue;
      }
      inSingleQuote = !inSingleQuote;
    } else if (char === '"' && !inSingleQuote) {
      inDoubleQuote = !inDoubleQuote;
    }
  }

  if (inSingleQuote) {
    const col = line.indexOf("'") + 1;
    return {
      line: state.line,
      column: col,
      message: "Unterminated string: missing closing single quote",
    };
  }

  if (inDoubleQuote) {
    const col = line.indexOf('"') + 1;
    return {
      line: state.line,
      column: col,
      message: "Unterminated string: missing closing double quote",
    };
  }

  return null;
}

function validateListItem(
  line: string,
  trimmed: string,
  state: ParserState,
  _currentIndent: number
): YamlError | null {
  const dashIndex = line.indexOf("-");

  if (dashIndex >= 0 && dashIndex < line.length - 1) {
    const afterDash = line[dashIndex + 1];

    if (afterDash !== " " && afterDash !== "\t" && trimmed !== "-") {
      const invalidPattern = line.substring(dashIndex).match(/^-[^\s]/);
      if (invalidPattern) {
        return {
          line: state.line,
          column: dashIndex + 1,
          message: "Invalid list item: dash must be followed by a space",
        };
      }
    }
  }

  return null;
}

function isKeyValueLine(trimmed: string): boolean {
  if (trimmed.startsWith("- ") || trimmed === "-") {
    return false;
  }

  const colonIndex = findUnquotedColon(trimmed);
  return colonIndex > 0;
}

function findUnquotedColon(str: string): number {
  let inSingleQuote = false;
  let inDoubleQuote = false;
  let escaped = false;

  for (let i = 0; i < str.length; i++) {
    const char = str[i];

    if (escaped) {
      escaped = false;
      continue;
    }

    if (char === "\\" && inDoubleQuote) {
      escaped = true;
      continue;
    }

    if (char === "'" && !inDoubleQuote) {
      if (inSingleQuote && str[i + 1] === "'") {
        i++;
        continue;
      }
      inSingleQuote = !inSingleQuote;
    } else if (char === '"' && !inSingleQuote) {
      inDoubleQuote = !inDoubleQuote;
    } else if (char === ":" && !inSingleQuote && !inDoubleQuote) {
      if (i + 1 >= str.length || str[i + 1] === " " || str[i + 1] === "\t" || str[i + 1] === "\n") {
        return i;
      }
    }
  }

  return -1;
}

function extractKey(trimmed: string): string | null {
  const colonIndex = findUnquotedColon(trimmed);
  if (colonIndex <= 0) return null;

  let key = trimmed.substring(0, colonIndex).trim();

  if ((key.startsWith('"') && key.endsWith('"')) || (key.startsWith("'") && key.endsWith("'"))) {
    key = key.slice(1, -1);
  }

  return key;
}

function validateKey(
  line: string,
  trimmed: string,
  state: ParserState,
  keyTrackers: KeyTracker[],
  currentIndent: number
): YamlError | null {
  const key = extractKey(trimmed);

  if (key === null || key.length === 0) {
    const colonIndex = line.indexOf(":");
    if (colonIndex >= 0) {
      return {
        line: state.line,
        column: colonIndex + 1,
        message: "Invalid key syntax: empty or malformed key before colon",
      };
    }
    return null;
  }

  if (!/^[\w\s\-_.'"[\]{}()@$%^&*+=<>?/\\|~`!]+$/i.test(key) && !key.startsWith('"') && !key.startsWith("'")) {
    const colonIndex = line.indexOf(":");
    return {
      line: state.line,
      column: colonIndex + 1,
      message: `Invalid key syntax: key contains invalid characters`,
    };
  }

  let tracker = keyTrackers.find((t) => t.indent === currentIndent);
  if (!tracker) {
    tracker = { indent: currentIndent, keys: new Set() };
    keyTrackers.push(tracker);
  } else if (tracker.indent === currentIndent) {
    if (tracker.keys.has(key)) {
      const colonIndex = line.indexOf(":");
      return {
        line: state.line,
        column: colonIndex - key.length + 1,
        message: `Duplicate key: "${key}" already defined at this indentation level`,
      };
    }
  }

  tracker.keys.add(key);

  return null;
}

function checkMultilineIndicator(trimmed: string): string | null {
  const colonIndex = findUnquotedColon(trimmed);
  if (colonIndex < 0) return null;

  const afterColon = trimmed.substring(colonIndex + 1).trim();

  if (afterColon === "|" || afterColon === "|-" || afterColon === "|+") {
    return "|";
  }
  if (afterColon === ">" || afterColon === ">-" || afterColon === ">+") {
    return ">";
  }

  return null;
}

