  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const lineNum = i + 1;
    const trimmed = line.trimStart();
    const leadingSpaces = line.length - trimmed.length;

    // Skip empty lines and comments
    if (trimmed === '' || trimmed.startsWith('#')) {
      continue;
    }

    // Check for document markers
    if (trimmed === '---' || trimmed === '...') {
      // Reset state for new document
      indentStack = [0];
      inMultilineString = false;
      continue;
    }

    // Check for tabs (YAML should use spaces)
    if (line.includes('\t')) {
      errors.push({
        line: lineNum,
        column: line.indexOf('\t') + 1,
        message: 'Tabs are not allowed in YAML, use spaces for indentation',
        type: 'indentation'
      });
    }

    // Handle multiline strings (literal | and folded >)
    if (inMultilineString) {
      if (leadingSpaces <= multilineStringIndent && trimmed !== '') {
        inMultilineString = false;
        multilineStringType = null;
      } else {
        continue;
      }
    }

    // Track flow context (braces and brackets)
    for (const char of line) {
      if (char === '{' || char === '[') inFlowContext++;
      if (char === '}' || char === ']') inFlowContext--;
    }

    // Skip indentation checks inside flow context
    if (inFlowContext > 0) {
      continue;
    }

    // Check indentation consistency (must be consistent increments)
    if (leadingSpaces > 0) {
      const lastIndent = indentStack[indentStack.length - 1];

      if (leadingSpaces > lastIndent) {
        // New indent level
        indentStack.push(leadingSpaces);
      } else if (leadingSpaces < lastIndent) {
