      indentStack = [0];
    }

    // Check for unterminated strings
    const singleQuoteCount = (trimmed.match(/'/g) || []).length;
    const doubleQuoteCount = (trimmed.match(/"/g) || []).length;
    const escapedSingleQuotes = (trimmed.match(/''/g) || []).length * 2;
    const escapedDoubleQuotes = (trimmed.match(/\\"/g) || []).length;

    // Adjust for escaped quotes
    const effectiveSingleQuotes = singleQuoteCount - escapedSingleQuotes;
    const effectiveDoubleQuotes = doubleQuoteCount - escapedDoubleQuotes;

    if (effectiveSingleQuotes % 2 !== 0) {
      errors.push({
        line: lineNum,
        column: line.indexOf("'") + 1,
        message: 'Unterminated single-quoted string',
        type: 'string'
      });
    }

    if (effectiveDoubleQuotes % 2 !== 0) {
      errors.push({
        line: lineNum,
        column: line.indexOf('"') + 1,
        message: 'Unterminated double-quoted string',
        type: 'string'
      });
    }

    // Check for multiline string indicators
    if (trimmed.match(/:\s*[|>][-+]?\s*(#.*)?$/)) {
      inMultilineString = true;
      multilineStringIndent = leadingSpaces;
      multilineStringType = trimmed.includes('|') ? '|' : '>';
      continue;
    }

    // Check for malformed keys
    // Key patterns: "key:", "key :", "'key':", '"key":'
    const keyMatch = trimmed.match(/^([^\s:]+)\s*:/);
    if (keyMatch) {
      const key = keyMatch[1];

      // Check for invalid characters in unquoted keys
      if (!key.startsWith("'") && !key.startsWith('"')) {
        // Unquoted keys shouldn't start with special chars
        if (/^[@`]/.test(key)) {
          errors.push({
            line: lineNum,
            column: leadingSpaces + 1,
            message: `Invalid key: unquoted keys cannot start with '${key[0]}'`,
            type: 'key'
          });
        }

        // Check for spaces in unquoted keys (malformed)
        if (key.includes(' ')) {
          errors.push({
            line: lineNum,
            column: leadingSpaces + 1,
            message: 'Malformed key: unquoted keys cannot contain spaces',
            type: 'key'
          });
        }
      }
    }

    // Check for list items
    if (trimmed.startsWith('- ') || trimmed === '-') {
      // List item - valid
      continue;
    }

    // Check for colon without space after it (common error in mappings)
    if (trimmed.match(/^[^#"']*[^:\s]:[^\s]/) && !trimmed.includes('://')) {
      // Exclude URLs (://)
      const colonPos = trimmed.search(/[^:\s]:[^\s]/);
      if (colonPos !== -1 && !trimmed.substring(0, colonPos + 2).includes('"') && !trimmed.substring(0, colonPos + 2).includes("'")) {
        // This is actually valid in some YAML contexts, but can indicate errors
        // We'll flag it as a warning-level item
      }
    }

    // Check for duplicate colons (common typo)
    if (trimmed.match(/::\s/)) {
      errors.push({
        line: lineNum,
        column: trimmed.indexOf('::') + leadingSpaces + 1,
        message: 'Possible typo: double colon (::) found',
        type: 'structure'
      });
    }
  }

  // Check for unclosed flow context
  if (inFlowContext > 0) {
    errors.push({
      line: lines.length,
      column: 1,
      message: `Unclosed flow context: ${inFlowContext} unclosed brace(s) or bracket(s)`,
      type: 'structure'
    });
  } else if (inFlowContext < 0) {
    errors.push({
      line: lines.length,
      column: 1,
      message: `Extra closing brace(s) or bracket(s)`,
      type: 'structure'
    });
  }

  return {
    valid: errors.length === 0,
    errors
  };
}

