/**
 * YAML Validator CLI - Zero-dependency command-line YAML syntax validator
 *
 * This module provides CLI components for validating YAML files:
 * - CLI argument parsing (--quiet, --help, file arguments)
 * - File reading with security checks and error handling
 * - Error formatting for stderr output
 */

import { resolve } from "node:path";
import type { YamlError } from "./yaml-parser";

// ============================================================================
// Types
// ============================================================================

export interface CliOptions {
  files: string[];
  quiet: boolean;
  help: boolean;
}

export interface FileReadResult {
  content?: string;
  error?: string;
}

// ============================================================================
// T2: CLI Argument Parser
// ============================================================================

/**
 * Parse command-line arguments into structured options.
 *
 * @param args - Command-line arguments (typically process.argv.slice(2))
 * @returns CliOptions object with files, quiet, and help properties
 *
 * Supports:
 * - `-q` or `--quiet` for quiet mode
 * - `-h` or `--help` for help display
 * - All other arguments are collected as file paths/patterns
 *
 * Edge cases:
 * - No arguments: returns empty files array
 * - Only flags: returns empty files array with flags set
 * - Mixed flags and files: correctly separates them
 */
export function parseArgs(args: string[]): CliOptions {
  const options: CliOptions = {
    files: [],
    quiet: false,
    help: false,
  };

  for (const arg of args) {
    if (arg === "-q" || arg === "--quiet") {
      options.quiet = true;
    } else if (arg === "-h" || arg === "--help") {
      options.help = true;
    } else if (!arg.startsWith("-")) {
      options.files.push(arg);
    }
  }

  return options;
}

// ============================================================================
// T3: File Reader
// ============================================================================

const MAX_FILE_SIZE = 10 * 1024 * 1024; // 10MB

/**
 * Check if a path is a local filesystem path (not a URL).
 *
 * @param path - Path to check
 * @returns true if the path is local, false if it's a URL
 */
function isLocalPath(path: string): boolean {
  if (/^[a-z]+:\/\//i.test(path)) {
    return false;
  }
  return true;
}

/**
 * Check if a path attempts to traverse outside the current working directory.
 *
 * @param normalizedPath - Absolute resolved path
 * @param originalPath - Original path before resolution
 * @returns true if the path is safe, false if it attempts traversal
 */
function isSafePath(normalizedPath: string, originalPath: string): boolean {
  const cwd = process.cwd();

  if (normalizedPath.startsWith(cwd)) {
    return true;
  }

  if (!originalPath.includes("..")) {
    return true;
  }

  return false;
}

/**
 * Read a YAML file with security checks and error handling.
 *
 * @param path - Path to the YAML file
 * @returns FileReadResult with content on success, error message on failure
 *
 * Security checks:
 * - Rejects remote URLs (http://, ftp://, etc.)
 * - Rejects path traversal attempts outside working directory
 * - Enforces 10MB file size limit
 *
 * Error handling:
 * - File not found
 * - Permission denied
 * - File too large
 * - Generic read errors
 */
export async function readYamlFile(path: string): Promise<FileReadResult> {
  if (!isLocalPath(path)) {
    return { error: "Only local file paths are allowed" };
  }

  const normalizedPath = resolve(path);

  if (!isSafePath(normalizedPath, path)) {
    return { error: "Path traversal outside working directory is not allowed" };
  }

  try {
    const file = Bun.file(normalizedPath);

    const exists = await file.exists();
    if (!exists) {
      return { error: `File not found: ${path}` };
    }

    const size = file.size;
    if (size > MAX_FILE_SIZE) {
      return { error: `File too large: ${path} (${Math.round(size / 1024 / 1024)}MB exceeds 10MB limit)` };
    }

    const content = await file.text();
    return { content };
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);

    if (message.includes("EACCES") || message.includes("permission")) {
      return { error: `Permission denied: ${path}` };
    }

    return { error: `Cannot read file: ${message}` };
  }
}

// ============================================================================
// T4: Error Formatter
// ============================================================================

/**
 * Format a YAML validation error in standard linter format.
 *
 * @param file - Path to the file containing the error
 * @param error - YamlError object with line, column, and message
 * @returns Formatted string in "file:line:col: message" format
 *
 * Example output:
 *   config/app.yaml:15:3: Invalid indentation - expected 4 spaces, got 3
 */
export function formatError(file: string, error: YamlError): string {
  return `${file}:${error.line}:${error.column}: ${error.message}`;
}

/**
 * Format a file access error.
 *
 * @param file - Path to the file
 * @param message - Error message describing the access problem
 * @returns Formatted string in "file: message" format
 *
 * Example output:
 *   config/db.yaml: File not found
 */
export function formatFileError(file: string, message: string): string {
  return `${file}: ${message}`;
}

