import { parseArgs, readYamlFile, formatError, formatFileError } from "./src/yaml-validator";

// Test T2: parseArgs
console.log("=== T2: parseArgs tests ===");

// Test 1: Empty arguments
const result1 = parseArgs([]);
console.log("Empty args:", JSON.stringify(result1));
console.assert(result1.files.length === 0, "Empty args should have no files");
console.assert(result1.quiet === false, "Empty args should have quiet=false");
console.assert(result1.help === false, "Empty args should have help=false");

// Test 2: Only flags
const result2 = parseArgs(["-q", "--help"]);
console.log("Only flags:", JSON.stringify(result2));
console.assert(result2.quiet === true, "Should recognize -q flag");
console.assert(result2.help === true, "Should recognize --help flag");
console.assert(result2.files.length === 0, "Flags only should have no files");

// Test 3: Mixed flags and files
const result3 = parseArgs(["--quiet", "file1.yaml", "-h", "file2.yml"]);
console.log("Mixed:", JSON.stringify(result3));
console.assert(result3.quiet === true, "Should recognize --quiet flag");
console.assert(result3.help === true, "Should recognize -h flag");
console.assert(result3.files.length === 2, "Should have 2 files");
console.assert(result3.files[0] === "file1.yaml", "First file should be file1.yaml");
console.assert(result3.files[1] === "file2.yml", "Second file should be file2.yml");

// Test 4: Only files
const result4 = parseArgs(["a.yaml", "b.yml", "c.yaml"]);
console.log("Only files:", JSON.stringify(result4));
console.assert(result4.files.length === 3, "Should have 3 files");
console.assert(result4.quiet === false, "Should have quiet=false");
console.assert(result4.help === false, "Should have help=false");

console.log("T2: All tests passed!");

// Test T3: readYamlFile
console.log("\n=== T3: readYamlFile tests ===");

// Test URL rejection
const urlResult = await readYamlFile("http://example.com/file.yaml");
console.log("URL rejection:", urlResult.error);
console.assert(urlResult.error === "Only local file paths are allowed", "Should reject URLs");

const ftpResult = await readYamlFile("ftp://example.com/file.yaml");
console.assert(ftpResult.error === "Only local file paths are allowed", "Should reject FTP URLs");

// Test non-existent file
const missingResult = await readYamlFile("nonexistent.yaml");
console.log("Missing file:", missingResult.error);
console.assert(missingResult.error?.includes("File not found"), "Should report file not found");

// Test reading existing file
const existingResult = await readYamlFile("./src/yaml-parser.ts");
console.log("Existing file:", existingResult.content ? "Read successfully (" + existingResult.content.length + " bytes)" : existingResult.error);
console.assert(existingResult.content && existingResult.content.length > 0, "Should read existing file");

console.log("T3: All tests passed!");

// Test T4: formatError and formatFileError
